INSERT INTO public.kb_translations VALUES
	('461428fc-e6ef-401e-a318-b8de61cb527e', 'en', 'Beskrivning av planerad EU-ansökan', 'Description of the planned EU application', '2026-09-03 21:22:47.133959+00'),
	('6a93bbb9-91e2-4ad5-aed5-f53d32a2f4fc', 'en', 'Beskrivning av utvecklingsinsatsen', 'Description of the development initiative', '2026-09-03 21:22:47.133959+00'),
	('fc0c341c-8773-48d4-992b-d167e2a3e721', 'en', 'Beskrivning av åtgärden', 'Description of the measure', '2026-09-03 21:22:47.133959+00'),
	('d7b268ca-3c0d-4eba-aa6e-ae932672f4b7', 'en', 'Betalar den andra föräldern inget eller mindre än fullt underhåll?', 'Does the other parent pay nothing, or less than full maintenance?', '2026-09-03 21:22:47.133959+00'),
	('29fe42d0-0b73-48c0-b360-533ff3d0a411', 'en', 'Betalar den andra föräldern inget, för lite eller oregelbundet? Konkret — det avgör vilken väg Försäkringskassan tar.', 'Does the other parent pay nothing, too little, or irregularly? Be concrete — it decides which route Försäkringskassan takes.', '2026-09-03 21:22:47.133959+00'),
	('b9ca97e5-adc9-4db2-9b4e-3257d51907ae', 'en', 'Betalar du hyra eller andra boendekostnader?', 'Do you pay rent or other housing costs?', '2026-09-03 21:22:47.133959+00'),
	('6a82435e-d045-4534-b494-31df3c79fc93', 'en', 'Betalas normalt ut automatiskt tillsammans med barnbidraget.', 'It is normally paid out automatically together with barnbidraget.', '2026-09-03 21:22:47.133959+00'),
	('7f5f047e-4e91-4f04-a2a0-166debc06f72', 'en', 'Betalas normalt ut automatiskt; ansökan i särskilda fall på Mina sidor hos Försäkringskassan.', 'It is normally paid out automatically; in special cases you apply in Mina sidor at Försäkringskassan.', '2026-09-03 21:22:47.133959+00'),
	('9d0a7bdb-0782-4455-b324-af30827bc799', 'en', 'Bidrag för att anpassa bostaden vid funktionsnedsättning — t.ex. ramper, dörröppnare eller badrumsanpassning.', 'A grant for adapting your home in case of disability — e.g. ramps, door openers or bathroom adaptations.', '2026-09-03 21:22:47.133959+00'),
	('2b245aa3-855a-46a9-be88-8e3e9f8dd77c', 'en', 'Bidrag för att bygga, köpa eller rusta upp allmänna samlingslokaler.', 'Grants for building, buying or renovating public assembly halls.', '2026-09-03 21:22:47.133959+00'),
	('c2ed4c8f-84b8-4510-bdaa-e87e12f972bb', 'en', 'Bidrag för att köpa eller anpassa en bil när en varaktig funktionsnedsättning gör det mycket svårt att förflytta sig eller resa kollektivt.', 'A grant for buying or adapting a car when a lasting disability makes it very difficult to get around or travel by public transport.', '2026-09-03 21:22:47.133959+00'),
	('b693350a-bddc-43e4-ad58-c926878df828', 'en', 'Bidrag för internationella resor och utbyten för yrkesverksamma inom kulturområdet.', 'Grants for international travel and exchanges for professionals in the cultural sector.', '2026-09-03 21:22:47.133959+00'),
	('b3b36e8a-53e6-4ea6-9a44-1f67650040e9', 'en', 'Bidrag för yrkesverksamma konstnärers internationella utbyten, resor och arbetsvistelser.', 'Grants for professional artists'' international exchanges, travel and working stays.', '2026-09-03 21:22:47.133959+00'),
	('d7a4a035-30a1-4400-9fb2-42a38993c294', 'en', 'Bidrag ges till avgränsade projekt, inte löpande verksamhet', 'Grants are given to defined projects, not to ongoing operations', '2026-09-03 21:22:47.133959+00'),
	('ef343a51-04a8-49cf-940c-144daca08546', 'en', 'Bidrag och frivilligt lån för dig som studerar på gymnasial eller eftergymnasial nivå.', 'A grant and optional loan for studies at upper secondary or post-secondary level.', '2026-09-03 21:22:47.133959+00'),
	('01625c35-4a12-4e1f-9e7c-29e737519b85', 'en', 'Bidrag och lån', 'Grant and loan', '2026-09-03 21:22:47.133959+00'),
	('d76d98ba-1bb3-4a62-80bf-fb6cda40c450', 'en', 'Bidrag och lån för studier utomlands, med extra merkostnadslån för t.ex. terminsavgifter och resor.', 'Grants and loans for studies abroad, with extra supplementary loans for e.g. tuition fees and travel.', '2026-09-03 21:22:47.133959+00'),
	('fe41cb24-d254-4d53-ba98-781992589196', 'en', 'Bidrag som hjälper svenska aktörer att förbereda ansökningar till EU-program som Horisont Europa.', 'A grant that helps Swedish actors prepare applications for EU programmes such as Horisont Europa.', '2026-09-03 21:22:47.133959+00'),
	('a5257e96-5422-4b36-a017-f3b8704e814c', 'en', 'Bidrag till arbetsgivare som anställer personer med nedsatt arbetsförmåga.', 'A grant for employers who hire people with reduced work capacity.', '2026-09-03 21:22:47.133959+00'),
	('2a61686f-25b1-42c5-a0fa-f4d2b88a5272', 'en', 'Bidrag till boende och hemresor när en gymnasieelev måste bo på studieorten på grund av lång resväg.', 'A grant towards lodging and journeys home when an upper secondary pupil has to live in the town of study because of a long journey.', '2026-09-03 21:22:47.133959+00'),
	('00a86124-8bf2-4fa8-be7c-4d9afeb806ee', 'en', 'Bidrag till ideella organisationers arbete med att bevara, använda och utveckla kulturarvet.', 'Grants for non-profit organisations'' work to preserve, use and develop cultural heritage.', '2026-09-03 21:22:47.133959+00'),
	('b70628d3-019e-41b6-ab53-525491d8d68c', 'en', 'Bidrag till kommunala och lokala naturvårdsprojekt, inklusive våtmarker och friluftsliv.', 'Grants for municipal and local nature conservation projects, including wetlands and outdoor recreation.', '2026-09-03 21:22:47.133959+00'),
	('ded8d88e-617b-4124-9ed8-eee11e044250', 'en', 'Bidrag till kommuner för inköp av litteratur till folk- och skolbibliotek.', 'Grants to municipalities for purchasing literature for public and school libraries.', '2026-09-03 21:22:47.133959+00'),
	('ef783ff3-382b-4d60-9410-3a032ce9b7d7', 'en', 'Bidrag till skolhuvudmän för elevers möte med professionell kultur i grundskolan.', 'Grants to school authorities for pupils'' encounters with professional culture in compulsory school.', '2026-09-03 21:22:47.133959+00'),
	('7520749a-d581-40da-a119-1c637d065f9c', 'en', 'Bidrag till sådant ditt barn behöver men som ekonomin inte räcker till: fritidsaktiviteter, kläder, skolutflykter, glasögon, lovaktiviteter med mera.', 'Grants for things your child needs but the family finances cannot cover: leisure activities, clothes, school outings, glasses, holiday activities and more.', '2026-09-03 21:22:47.133959+00'),
	('8b1fd5f8-1df1-489f-a2f4-e5c650683b11', 'en', 'Bidrag ur bl.a. Världens Barn, Musikhjälpen och Victoriafonden — söks av svenska ideella organisationer med 90-konto.', 'Grants from funds such as Världens Barn, Musikhjälpen and Victoriafonden — applied for by Swedish non-profit organisations with a 90-konto.', '2026-09-03 21:22:47.133959+00'),
	('acd00513-a697-46fd-8a6a-171fa8919c69', 'en', 'Bidrag ur vattenkrafts- och vindkraftsmedel till projekt som utvecklar bygden.', 'Grants from hydropower and wind power funds for projects that develop the local community.', '2026-09-03 21:22:47.133959+00'),
	('ab7cc05e-a57a-4a3b-9584-c35431787323', 'en', 'Bidrag utan lånedel för arbetslösa 25–60 år med kort tidigare utbildning som behöver studera på grundskole- eller gymnasienivå.', 'A grant with no loan component for unemployed people aged 25–60 with short previous education who need to study at compulsory or upper secondary level.', '2026-09-03 21:22:47.133959+00'),
	('74574f75-da8c-4854-8af8-ecc1e7b319ce', 'en', 'Bidragen söks av ideella föreningar', 'The grants are applied for by non-profit associations', '2026-09-03 21:22:47.133959+00'),
	('bd47a24b-418d-4e2c-9ffe-69f950a71bb0', 'en', 'Bidragen söks av ideella organisationer', 'The grants are applied for by non-profit organisations', '2026-09-03 21:22:47.133959+00'),
	('7c579d21-28ba-4494-af8a-c75703e0afec', 'en', 'Bidragen söks i regel av ideella organisationer', 'The grants are as a rule applied for by non-profit organisations', '2026-09-03 21:22:47.133959+00'),
	('24ac0c3e-ad75-45c0-9a5c-b3f59ef072a4', 'en', 'Bidraget beräknas delvis på ytan — siffran står i hyresavtalet.', 'The grant is partly calculated on floor area — the figure is in your tenancy agreement.', '2026-09-03 21:22:47.133959+00'),
	('41c2e701-90de-4d2f-9adf-b3cdb619326e', 'en', 'Bidraget förvaltas av ett svenskt lärosäte — det ska bekräfta åtagandet.', 'The grant is administered by a Swedish higher-education institution — it must confirm the commitment.', '2026-09-03 21:22:47.133959+00'),
	('1d5a8e79-ecbe-4da0-8aa7-c557cf062911', 'en', 'Bidraget gäller från och med det år du fyller 24', 'The benefit applies from the year you turn 24', '2026-09-03 21:22:47.133959+00'),
	('014a0a87-de10-4b36-9092-1d52dd1442a5', 'en', 'Bidraget gäller privatpersoner', 'The benefit is for private individuals', '2026-09-03 21:22:47.133959+00'),
	('a2599d88-cb55-4956-bd35-224a8571d32a', 'en', 'Bidraget ska användas för att förbereda en EU-ansökan', 'The grant must be used to prepare an EU application', '2026-09-03 21:22:47.133959+00'),
	('ac83c45c-4271-4642-b75c-3a93f46f867e', 'en', 'Bidraget stäms av mot årsinkomsten i efterhand — en för låg uppskattning kan ge återkrav.', 'The benefit is reconciled against your annual income afterwards — an estimate that is too low can lead to a repayment demand.', '2026-09-03 21:22:47.133959+00'),
	('02843d14-835a-44c4-b5af-993bfe230f67', 'en', 'Bidraget söks av enskilda yrkesverksamma konstnärer', 'The grant is applied for by individual professional artists', '2026-09-03 21:22:47.133959+00'),
	('1cbf2e71-d840-4035-8f4b-79fa155015c8', 'en', 'Bidraget söks av privatpersoner', 'The benefit is applied for by private individuals', '2026-09-03 21:22:47.133959+00'),
	('f7eafaff-bfcc-4024-8b31-6e5870d53827', 'en', 'Bidraget söks av vårdnadshavare', 'The benefit is applied for by a guardian', '2026-09-03 21:22:47.133959+00'),
	('7b6b1034-6443-4bac-805e-719b28420fa4', 'en', 'Bidraget söks för barn av vårdnadshavare', 'The benefit is applied for on behalf of a child by a guardian', '2026-09-03 21:22:47.133959+00'),
	('fdfb5752-9469-45d3-9586-5acf480d2977', 'en', 'Bidraget söks för barn av vårdnadshavare eller t.ex. skolsköterska', 'The benefit is applied for on behalf of a child by a guardian or, for example, a school nurse', '2026-09-03 21:22:47.133959+00'),
	('1ee5b50f-95f4-46ff-a49b-2582240d5755', 'en', 'Bidraget är högst halva kostnaden per laddpunkt, med takbelopp.', 'The grant covers at most half the cost per charging point, subject to a ceiling.', '2026-09-03 21:22:47.133959+00'),
	('3d22dc60-03bf-4230-9e97-8d9eac1da797', 'en', 'Bidragets tak varierar mellan regioner — hela kostnaden ersätts inte alltid.', 'The ceiling varies between regions — the full cost is not always reimbursed.', '2026-09-03 21:22:47.133959+00'),
	('9cbb528d-d276-4af8-ba4d-dbfde9b8ace1', 'en', 'Bidrar projektet till energiomställningen?', 'Does the project contribute to the energy transition?', '2026-09-03 21:22:47.133959+00'),
	('b80dcd24-7692-45b0-838b-66b49db9e45c', 'en', 'Bidrar till energiomställningen', 'Contributes to the energy transition', '2026-09-03 21:22:47.133959+00'),
	('5e719d7c-8cff-4f04-a95f-5dc6e0c9c448', 'en', 'Boende, försörjning och nätverk i ursprungslandet. OBS: beslutet är oåterkalleligt i bidragshänseende — uppehållstillståndet återkallas normalt. Ta det lugnt med beslutet och kontrollera aktuella belopp hos Migrationsverket.', 'Housing, income and networks in the country of origin. NOTE: in terms of this benefit the decision is irreversible — the residence permit is normally revoked. Take your time with the decision and check the current amounts with Migrationsverket.', '2026-09-03 21:22:47.133959+00'),
	('53e6da70-61fd-459e-826d-bca0f3a0d505', 'en', 'Boendekostnad per månad (kr)', 'Housing cost per month (kr)', '2026-09-03 21:22:47.133959+00'),
	('5a52a139-206e-46aa-9aba-b7028ac96a19', 'en', 'Bolaget', 'The company', '2026-09-03 21:22:47.133959+00'),
	('ce552440-d30a-4ff8-aa18-083df2d69b8f', 'en', 'Bolaget ska vara registrerat i Sverige', 'The company must be registered in Sweden', '2026-09-03 21:22:47.133959+00');
INSERT INTO public.kb_translations VALUES
	('6fd718d6-09e1-4a49-b1ff-c8f11593e556', 'en', 'Bolaget ska vara ungt (typiskt max ca 5 år — se aktuell utlysning)', 'The company must be young (typically no more than about 5 years — see the current call)', '2026-09-03 21:22:47.133959+00'),
	('7aa6710f-4026-4089-8530-6fe9592160f8', 'en', 'Bolagets namn', 'Name of the company', '2026-09-03 21:22:47.133959+00'),
	('986aa97f-ecda-4361-beac-311e713f8380', 'en', 'Bor du ensam i egen bostad?', 'Do you live alone in your own home?', '2026-09-03 21:22:47.133959+00'),
	('84b7cf0f-1e36-4785-8a08-c1dff6757b7e', 'en', 'Bor du och barnets andra förälder på skilda håll?', 'Do you and the child''s other parent live apart?', '2026-09-03 21:22:47.133959+00'),
	('2b417825-f9e4-4e00-8121-c2347d892869', 'en', 'Bostaden', 'The home', '2026-09-03 21:22:47.133959+00'),
	('ff269d7e-9902-4d40-8a5e-79f2eb4df47b', 'en', 'Bostaden ska behöva anpassas', 'The home must be in need of adaptation', '2026-09-03 21:22:47.133959+00'),
	('c55cd901-52aa-40a5-8db0-f539b443e1af', 'en', 'Bostaden ska ligga i Sverige', 'The home must be located in Sweden', '2026-09-03 21:22:47.133959+00'),
	('56815f14-e1a0-4cf6-a74a-14814f4e4daf', 'en', 'Bostadens yta (kvm)', 'Floor area of the home (m²)', '2026-09-03 21:22:47.133959+00'),
	('5be250d5-078b-43fd-afde-60902d2edfbc', 'en', 'Bostadsbidraget stäms av mot årsinkomsten i efterhand — en för låg uppskattning kan ge återkrav. Ta i lite uppåt hellre än neråt.', 'Bostadsbidraget is reconciled against your annual income afterwards — an estimate that is too low can lead to a repayment demand. Better to estimate slightly high than slightly low.', '2026-09-03 21:22:47.133959+00'),
	('4260c7de-dfed-4c9f-b37c-179f5d7cc418', 'en', 'Budget', 'Budget', '2026-09-03 21:22:47.133959+00'),
	('c97c7c08-1d80-4362-b298-ee05f7bc576b', 'en', 'Budget enligt programmets schabloner', 'Budget using the programme''s standard rates', '2026-09-03 21:22:47.133959+00'),
	('bbce79a8-7681-42b5-bf18-d93d18bc1536', 'en', 'Budget och finansiering', 'Budget and financing', '2026-09-03 21:22:47.133959+00'),
	('f67fc57e-20cc-4347-8811-7ee315592604', 'en', 'Budget och överlevnad', 'Budget and long-term survival', '2026-09-03 21:22:47.133959+00'),
	('b2e61d47-0806-4897-8578-09b3dac63c2c', 'en', 'Byggnader, maskiner eller inventarier — och hur investeringen ökar sysselsättningen eller konkurrenskraften på orten.', 'Buildings, machinery or equipment — and how the investment increases employment or competitiveness locally.', '2026-09-03 21:22:47.133959+00'),
	('c98f8209-58ab-4c40-a3e0-f7ef09ee9a8e', 'en', 'Checkar till små företag för att ta in extern kompetens vid internationalisering eller digitalisering.', 'Vouchers for small companies to bring in external expertise for internationalisation or digitalisation.', '2026-09-03 21:22:47.133959+00'),
	('827a8163-a1da-448f-9d92-79301cfb6e42', 'en', 'Checkarna riktar sig typiskt till företag med 2–49 anställda — regionens villkor styr.', 'The cheques are typically aimed at companies with 2–49 employees — the region''s terms decide.', '2026-09-03 21:22:47.133959+00'),
	('7c0359a1-7e79-48c7-8038-5b184a97d665', 'en', 'Checken ska användas för utvecklingsinsats med extern kompetens', 'The cheque must be used for a development initiative involving external expertise', '2026-09-03 21:22:47.133959+00'),
	('79156cd1-e753-4d1d-b441-075b103577aa', 'en', 'Checken täcker normalt högst hälften av kostnaden — resten är egen insats.', 'The cheque normally covers at most half the cost — the rest is your own contribution.', '2026-09-03 21:22:47.133959+00'),
	('563e5014-b7c2-4902-860d-502a51c5a88a', 'en', 'CV eller konstnärlig meritförteckning', 'CV or artistic record of merits', '2026-09-03 21:22:47.133959+00'),
	('d424d35e-2199-40b8-8100-30abd8f269b0', 'en', 'CV för nyckelfunktioner', 'CVs for the key functions', '2026-09-03 21:22:47.133959+00'),
	('cc0ab738-d77f-43b2-a8d3-0e34c344ad82', 'en', 'CV för nyckelpersoner', 'CVs for the key people', '2026-09-03 21:22:47.133959+00'),
	('e1cabd6c-664a-424e-ac42-6e6ceaeda07e', 'en', 'CV och publikationslista', 'CV and list of publications', '2026-09-03 21:22:47.133959+00'),
	('64611674-0d88-4c4e-a229-7a94090f4eb3', 'en', 'Datum för start eller övertagande', 'Date of start or takeover', '2026-09-03 21:22:47.133959+00'),
	('ba4ae78f-ff06-4b1f-b879-9ca4428f692b', 'en', 'De flesta mindre företagsstöd är de minimis-stöd. Taket är 300 000 euro per treårsperiod — nytt stöd över taket är otillåtet, och uppgiften intygas på heder och samvete hos finansiären.', 'Most smaller business supports are de minimis aid. The ceiling is EUR 300 000 over a three-year period — new aid above the ceiling is not permitted, and you certify the figure on your honour to the funder.', '2026-09-03 21:22:47.133959+00'),
	('4e4b209c-b2ea-499b-b941-a222c3266773', 'en', 'Delaktigheten är ett skarpt krav — beskriv mekanismen, inte avsikten: vem ur målgruppen gör vad?', 'Participation is a hard requirement — describe the mechanism, not the intention: who from the target group does what?', '2026-09-03 21:22:47.133959+00'),
	('2fd9b979-f908-4fd2-acff-48b5a2078c22', 'en', 'Deltagare och partner', 'Participants and partners', '2026-09-03 21:22:47.133959+00'),
	('f1a5fdc8-5790-420f-a8e8-1edfb7b54ad7', 'en', 'Deltagarna ska vara 13–30 år', 'The participants must be aged 13–30', '2026-09-03 21:22:47.133959+00'),
	('46919d0b-1bfd-4f6d-afaa-63d6517c6273', 'en', 'Deltar du i ett program hos Arbetsförmedlingen (t.ex. jobb- och utvecklingsgarantin)?', 'Are you taking part in a programme at Arbetsförmedlingen (e.g. jobb- och utvecklingsgarantin)?', '2026-09-03 21:22:47.133959+00'),
	('ba2a0e6e-a27c-49db-b9fe-3ac3d0890195', 'en', 'Demokratisk uppbyggnad krävs', 'A democratic structure is required', '2026-09-03 21:22:47.133959+00'),
	('23011f39-0a25-474b-9ae2-2fb5638f8b10', 'en', 'Demokratiskt uppbyggd organisation', 'A democratically structured organisation', '2026-09-03 21:22:47.133959+00'),
	('89a516f4-9d5d-4e94-ad6b-18072c6f4c6e', 'en', 'Den andra föräldern betalar inte underhåll (eller för lite)', 'The other parent does not pay maintenance (or pays too little)', '2026-09-03 21:22:47.133959+00'),
	('fe618751-dfab-489c-8785-9eb5fdb5bd5b', 'en', 'Den anställda ska ha nedsatt arbetsförmåga på grund av funktionsnedsättning eller ohälsa', 'The employee must have reduced capacity to work because of a disability or ill health', '2026-09-03 21:22:47.133959+00'),
	('97a439a8-7e69-43c7-8ef9-e51312b791d7', 'en', 'Den som anställs ska ha varit borta från arbetslivet en längre tid eller vara nyanländ', 'The person being employed must have been away from working life for a long time or be a newly arrived immigrant', '2026-09-03 21:22:47.133959+00'),
	('c3f052f8-18a0-4340-9a6b-a07aee2e662e', 'en', 'Den som bor ensam kan ha rätt till bostadsersättning.', 'If you live alone you may be entitled to bostadsersättning (a housing supplement).', '2026-09-03 21:22:47.133959+00'),
	('425a23ec-c3ed-4c35-87b0-0b21df65b61c', 'en', 'Det här är prövningens kärna: koppla utbildningen till faktisk efterfrågan — en bransch som rekryterar, en roll din arbetsgivare behöver. Söktrycket är högt och generiska motiveringar sållas bort.', 'This is the heart of the assessment: link the training to actual demand — a sector that is recruiting, a role your employer needs. Competition is high and generic motivations are filtered out.', '2026-09-03 21:22:47.133959+00'),
	('bff18e3c-6175-46e1-8261-9db16cd897fa', 'en', 'Det ska finnas en sparbank/sparbanksstiftelse i ert verksamhetsområde', 'There must be a savings bank or savings-bank foundation in your area of operation', '2026-09-03 21:22:47.133959+00'),
	('2faae728-10b2-4c99-8384-7cd79626e37b', 'en', 'Det ska vara mycket svårt att förflytta sig på egen hand eller använda allmänna kommunikationer', 'It must be very difficult to get around on your own or to use public transport', '2026-09-03 21:22:47.133959+00'),
	('e8bfe01a-e08d-4b2e-9e0a-294ea9fff67d', 'en', 'Detaljerad budget', 'Detailed budget', '2026-09-03 21:22:47.133959+00'),
	('ac28acfd-661b-4119-9530-7568bbf29025', 'en', 'Detaljerad projektbudget', 'Detailed project budget', '2026-09-03 21:22:47.133959+00'),
	('5f155fc4-1120-48bb-bb56-b361d753f63d', 'en', 'Diagnos eller svårigheter i vardagen — läkarutlåtandet bär den medicinska bedömningen, din beskrivning bär vardagen.', 'A diagnosis or everyday difficulties — the doctor''s statement carries the medical assessment, your description carries daily life.', '2026-09-03 21:22:47.133959+00'),
	('a1545ecf-a58b-4994-9c53-cd6495746ea4', 'en', 'Din beräknade inkomst i år, före skatt (kr)', 'Your estimated income this year, before tax (kr)', '2026-09-03 21:22:47.133959+00'),
	('3440b3a0-d826-493d-8166-a0090474d540', 'en', 'Din inkomst ska vara låg', 'Your income must be low', '2026-09-03 21:22:47.133959+00'),
	('58e9b4eb-79ee-48a7-a62c-049b1f6a30ea', 'en', 'Din konstnärliga verksamhet', 'Your artistic work', '2026-09-03 21:22:47.133959+00'),
	('7fb83059-372a-4fc8-8268-d05a71786ce2', 'en', 'Din relation till den som är sjuk', 'Your relationship to the person who is ill', '2026-09-03 21:22:47.133959+00'),
	('4f531427-1af5-4d4b-9e18-04bf4db4e607', 'en', 'Din senast avslutade utbildning', 'Your most recently completed education', '2026-09-03 21:22:47.133959+00'),
	('92d51afe-d66d-4700-83ee-c2288a6f93b3', 'en', 'Din situation', 'Your situation', '2026-09-03 21:22:47.133959+00'),
	('e3d4ef45-1548-4910-8507-9f8d3d11e8ae', 'en', 'Din utbildning och erfarenhet inom området', 'Your education and experience in the field', '2026-09-03 21:22:47.133959+00'),
	('caf5b8e1-2fec-4ffb-92e8-a2a3b043d076', 'en', 'Ditt arbetsliv', 'Your working life', '2026-09-03 21:22:47.133959+00'),
	('9bf92fb6-9047-4626-a59c-4d9243e4534d', 'en', 'Du (eller ditt barn) ska ha en varaktig funktionsnedsättning', 'You (or your child) must have a lasting disability', '2026-09-03 21:22:47.133959+00'),
	('651961ab-2f9d-4bbc-9f7a-76786dedb666', 'en', 'Du eller någon i hushållet ska ha en bestående funktionsnedsättning', 'You or someone in the household must have a permanent disability', '2026-09-03 21:22:47.133959+00');
INSERT INTO public.kb_translations VALUES
	('aeb8cc2a-ecfd-4a8b-8614-fd6e73e53458', 'en', 'Du ska avstå från förvärvsarbete för att vårda eller vara nära en närstående vars sjukdom är ett påtagligt hot mot livet', 'You must refrain from gainful employment to care for or be close to a relative whose illness is a serious threat to life', '2026-09-03 21:22:47.133959+00'),
	('611652fb-e9ae-46bb-a125-90aa75a1877c', 'en', 'Du ska betala för ditt boende', 'You must pay for your housing', '2026-09-03 21:22:47.133959+00'),
	('656c71b8-288d-4b9b-aaa0-686674f8f7a0', 'en', 'Du ska bo i Sverige', 'You must live in Sweden', '2026-09-03 21:22:47.133959+00'),
	('2930c090-e152-43c0-9776-45aea47b6d84', 'en', 'Du ska delta i ett arbetsmarknadspolitiskt program', 'You must take part in a labour-market policy programme', '2026-09-03 21:22:47.133959+00'),
	('2d86a64a-9b33-4b41-aaf9-69b36f70acc0', 'en', 'Du ska frivilligt planera att flytta tillbaka till ditt ursprungsland permanent', 'You must voluntarily plan to move back to your country of origin permanently', '2026-09-03 21:22:47.133959+00'),
	('2c5d7af3-8c4d-42ae-84c7-72681e58738f', 'en', 'Du ska ha (eller vänta) barn som du avstår arbete för att ta hand om', 'You must have (or be expecting) a child that you are taking time off work to care for', '2026-09-03 21:22:47.133959+00'),
	('92832fd3-d19f-425a-a3d5-bcd549a491de', 'en', 'Du ska ha arbetat i genomsnitt minst 16 h/vecka i minst 8 år', 'You must have worked an average of at least 16 h/week for at least 8 years', '2026-09-03 21:22:47.133959+00'),
	('087ceb4e-6557-485f-9511-8c440612da7e', 'en', 'Du ska ha barn (normalt under 12 år) som du vårdar när det är sjukt', 'You must have a child (normally under 12) whom you care for when it is ill', '2026-09-03 21:22:47.133959+00'),
	('598055a6-c5ec-43e7-9de5-f39a098a5e7c', 'en', 'Du ska ha barn (upp till 18 år) som bor hos dig', 'You must have a child (up to 18) living with you', '2026-09-03 21:22:47.133959+00'),
	('838df142-59c8-40f9-adfd-d518a77d429c', 'en', 'Du ska ha barn som bor hos dig', 'You must have a child living with you', '2026-09-03 21:22:47.133959+00'),
	('7cedb2f6-8c2e-40cd-828e-cbe9c113ac3e', 'en', 'Du ska ha barn som bor hos dig (helt eller växelvis)', 'You must have a child living with you (full-time or alternating)', '2026-09-03 21:22:47.133959+00'),
	('405b8928-da44-4299-af15-9c687e4a1935', 'en', 'Du ska ha barn under 16 år som bor hos dig', 'You must have a child under 16 living with you', '2026-09-03 21:22:47.133959+00'),
	('1e00cee3-d3c5-4096-bebe-3d5a1812fe7e', 'en', 'Du ska ha kort tidigare utbildning och behöva studier på grundskole- eller gymnasienivå', 'You must have limited previous education and need studies at compulsory-school or upper-secondary level', '2026-09-03 21:22:47.133959+00'),
	('e5e16671-52b4-4fd8-9d76-26ad28836ab6', 'en', 'Du ska ha uppehållstillstånd som flykting eller skyddsbehövande (eller vara nära anhörig till någon som har det)', 'You must hold a residence permit as a refugee or person in need of protection (or be a close relative of someone who does)', '2026-09-03 21:22:47.133959+00'),
	('fb9840fb-c2a9-4669-bf8b-35876202bc68', 'en', 'Du ska ha uppnått riktåldern för pension (67 år från 2026)', 'You must have reached the reference age for pension (67 from 2026)', '2026-09-03 21:22:47.133959+00'),
	('5bb1f93b-18ed-4482-92b6-faf7dbd048a4', 'en', 'Partnerskapet', 'The partnership', '2026-09-03 21:22:47.154334+00'),
	('34dff8ee-62cd-40c5-8f79-d75c32c20b9e', 'en', 'Du ska nyligen ha fått uppehållstillstånd som skyddsbehövande eller anhörig', 'You must recently have received a residence permit as a person in need of protection or as a relative', '2026-09-03 21:22:47.133959+00'),
	('1c131026-3cbd-42cb-be8f-0cbe7118866e', 'en', 'Du ska planera att starta företag', 'You must be planning to start a business', '2026-09-03 21:22:47.133959+00'),
	('e182bc57-34f2-49c1-bf01-6c90e05574c3', 'en', 'Du ska planera studier som stärker din ställning på arbetsmarknaden', 'You must be planning studies that strengthen your position in the labour market', '2026-09-03 21:22:47.133959+00'),
	('e0969ace-2885-4d35-b7d1-ff547c7b2a52', 'en', 'Du ska sakna sparande eller tillgångar som kan täcka behoven', 'You must lack savings or assets that could cover the needs', '2026-09-03 21:22:47.133959+00'),
	('668261a2-5ba9-4395-a58b-892c6d906719', 'en', 'Du ska studera eller planera att börja studera', 'You must be studying or planning to start studying', '2026-09-03 21:22:47.133959+00'),
	('75e72685-fcb2-4cfe-ac93-81f7913a7630', 'en', 'Du ska söka eller ha fått jobb i ett annat EU-/EES-land', 'You must be seeking or have obtained a job in another EU/EEA country', '2026-09-03 21:22:47.133959+00'),
	('6b959e6d-2d16-4c09-8dca-03aa0830d302', 'en', 'Du ska ta ut hel allmän pension', 'You must draw a full general pension', '2026-09-03 21:22:47.133959+00'),
	('4f4d1dc3-f5d2-4d71-bf2e-cdb6250b8485', 'en', 'Du ska vara 19–29 år', 'You must be 19–29 years old', '2026-09-03 21:22:47.133959+00'),
	('944126da-5d6a-4c3f-97a1-f70e6aa1a5e6', 'en', 'Du ska vara arbetslös och anmäld hos Arbetsförmedlingen', 'You must be unemployed and registered with Arbetsförmedlingen', '2026-09-03 21:22:47.133959+00'),
	('bfd8cc79-06f8-40f4-aba2-81a50cc87f29', 'en', 'Du ska vara bosatt i ett EU-land (här: Sverige)', 'You must be resident in an EU country (here: Sweden)', '2026-09-03 21:22:47.133959+00'),
	('c9f7e586-346b-437c-8d0e-396a6af6e3b9', 'en', 'Du ska vara försäkrad i Sverige', 'You must be insured in Sweden', '2026-09-03 21:22:47.133959+00'),
	('f1eac05a-6127-4d6c-9021-6b02de68dfca', 'en', 'Du ska vara inskriven hos Arbetsförmedlingen', 'You must be registered with Arbetsförmedlingen', '2026-09-03 21:22:47.133959+00'),
	('59553709-5a32-42eb-8636-843ba5ed1be2', 'en', 'Du ska vara inskriven hos Arbetsförmedlingen i Sverige', 'You must be registered with Arbetsförmedlingen in Sweden', '2026-09-03 21:22:47.133959+00'),
	('cf8c2b54-7dbc-41a6-98a1-7e24b7caf9cd', 'en', 'Du ska vara inskriven hos Arbetsförmedlingen och aktivt söka arbete', 'You must be registered with Arbetsförmedlingen and actively looking for work', '2026-09-03 21:22:47.133959+00'),
	('5c2231d2-243c-488d-961d-8bcc5bb55857', 'en', 'Du ska vara inskriven hos Arbetsförmedlingen och delta i etableringsprogrammet', 'You must be registered with Arbetsförmedlingen and take part in the establishment programme', '2026-09-03 21:22:47.133959+00'),
	('92749218-f2cd-4d35-b795-2709f3a0694f', 'en', 'Du ska vara inskriven som arbetssökande', 'You must be registered as a jobseeker', '2026-09-03 21:22:47.133959+00'),
	('1d3583ba-c2da-4f5c-b7fa-095588962b88', 'en', 'Du ska vara mellan 18 och 28 år', 'You must be between 18 and 28 years old', '2026-09-03 21:22:47.133959+00'),
	('eb2f28ed-4226-4c71-a2d9-d4fe10064313', 'en', 'Du ska vara mellan 25 och 60 år', 'You must be between 25 and 60 years old', '2026-09-03 21:22:47.133959+00'),
	('a2f4f7a3-8a54-469b-9afc-06e635920822', 'en', 'Efterhandsstöd till förlag för utgivning av kvalitetslitteratur.', 'Retrospective support to publishers for publishing quality literature.', '2026-09-03 21:22:47.133959+00'),
	('b996483b-3de9-477f-80b2-fb760a2a6a8e', 'en', 'Egna medel, andra bidrag, intäkter. Lämna tomt om allt söks här.', 'Own funds, other grants, income. Leave blank if everything is being applied for here.', '2026-09-03 21:22:47.133959+00'),
	('c272faef-5de9-4efb-8c48-89906f3f4d24', 'en', 'Ekonomi', 'Finances', '2026-09-03 21:22:47.133959+00'),
	('c34f6e2e-ed5c-4fe8-b0f4-83bfba64e645', 'en', 'Ekonomi per månad', 'Monthly finances', '2026-09-03 21:22:47.133959+00'),
	('39e6431a-f70d-4bda-8cfc-4d13d8098bad', 'en', 'Ekonomin räcker inte till sådant barnet behöver eller förväntas delta i', 'Your finances are not enough for things the child needs or is expected to take part in', '2026-09-03 21:22:47.133959+00'),
	('da2b2b5a-e838-4b8d-8cab-7877b74453de', 'en', 'Ekonomisk kalkyl', 'Financial calculation', '2026-09-03 21:22:47.133959+00'),
	('eea358ae-e386-4675-a49d-3bde1dd01c68', 'en', 'Ekonomiskt stöd för den som har skyddsrelaterat uppehållstillstånd och frivilligt vill flytta tillbaka till sitt ursprungsland permanent.', 'Financial support for those with a protection-related residence permit who voluntarily want to move back to their country of origin permanently.', '2026-09-03 21:22:47.133959+00'),
	('20f00dde-6721-4838-beb8-15aba8b2fc67', 'en', 'Ekonomiskt stöd till arbetsgivare som anställer någon som varit borta länge från arbetslivet.', 'Financial support for employers who hire someone who has been away from working life for a long time.', '2026-09-03 21:22:47.133959+00'),
	('ddee0de9-058c-4499-a664-79522ccc3c1a', 'en', 'Ekonomiskt stöd under uppstarten för arbetssökande som startar eget företag.', 'Financial support during the start-up phase for jobseekers starting their own business.', '2026-09-03 21:22:47.133959+00'),
	('748c1d16-60c2-4154-a73a-4ec942949ecf', 'en', 'Eleven behöver bo på studieorten på grund av lång eller besvärlig resväg', 'The pupil needs to live in the town of study because of a long or difficult journey', '2026-09-03 21:22:47.133959+00'),
	('c318540e-4988-42ac-80ed-f98e69dbc05f', 'en', 'Eleven går på gymnasiet med studiehjälp', 'The pupil attends upper-secondary school and receives studiehjälp', '2026-09-03 21:22:47.133959+00'),
	('73038b6b-4325-41a5-bec3-c6890f7b0bf9', 'en', 'Eleven och resvägen', 'The pupil and the journey', '2026-09-03 21:22:47.133959+00'),
	('b4853ed3-5f50-4fb4-8584-40e33e2870e5', 'en', 'Eleven och skolvägen', 'The pupil and the way to school', '2026-09-03 21:22:47.133959+00'),
	('4f74a0c7-c9b3-418c-83c3-ea5bb4d96d4e', 'en', 'Elevens namn', 'The pupil''s name', '2026-09-03 21:22:47.133959+00'),
	('0fa4406a-5561-46e4-9fad-bf32fffea0d6', 'en', 'Elever som målgrupp', 'Pupils as the target group', '2026-09-03 21:22:47.133959+00'),
	('66971599-c164-4353-b722-1ebf684cad87', 'en', 'Elevresestödet förutsätter studiehjälp — den kommer automatiskt för de flesta gymnasieelever under 20.', 'Support for pupil travel presupposes studiehjälp — which most upper-secondary pupils under 20 receive automatically.', '2026-09-03 21:22:47.133959+00');
INSERT INTO public.kb_translations VALUES
	('7b8a34ed-e022-4e79-9cf9-b988b8dce75f', 'en', 'En energikartläggning eller leverantörsberäkning styrker siffran.', 'An energy survey or a supplier''s calculation supports the figure.', '2026-09-03 21:22:47.133959+00'),
	('054daa3f-bedd-4c5f-aab3-d3764f61b5dd', 'en', 'En påbörjad investering diskvalificerar hela ansökan — beställ inget förrän ansökan är inne.', 'An investment already begun disqualifies the entire application — order nothing until the application is submitted.', '2026-09-03 21:22:47.145935+00'),
	('2474b82d-3184-4abc-9f8b-7ede06e025d2', 'en', 'Energi-/klimatprojekt', 'Energy or climate project', '2026-09-03 21:22:47.145935+00'),
	('a28898e7-fc16-484e-8ed0-49d4230f04e4', 'en', 'Energimyndigheten öppnar löpande utlysningar inom energiforskning, innovation och energieffektivisering.', 'Energimyndigheten continuously opens calls within energy research, innovation and energy efficiency.', '2026-09-03 21:22:47.145935+00'),
	('0061456e-998d-4c36-9de6-06e524b7a538', 'en', 'Ersättning för att vara ledig från arbete eller studier för att ta hand om barn.', 'Compensation for taking time off work or studies to care for a child.', '2026-09-03 21:22:47.145935+00'),
	('32fbf66f-0d6a-40ff-b9fc-cb802a94ff7f', 'en', 'Ersättning för den som är ny i Sverige och deltar i etableringsprogrammet hos Arbetsförmedlingen; betalas ut av Försäkringskassan.', 'Compensation for those who are new in Sweden and take part in the establishment programme at Arbetsförmedlingen; paid out by Försäkringskassan.', '2026-09-03 21:22:47.145935+00'),
	('cfae426e-111e-463b-a299-3fd9948e9a5d', 'en', 'Ersättning för en del av boendekostnaden för unga utan barn med låga inkomster.', 'Compensation for part of the housing cost for young people without children on low incomes.', '2026-09-03 21:22:47.145935+00'),
	('892eb321-111d-4017-9697-ae7c30dcec73', 'en', 'Ersättning för merkostnader som en varaktig funktionsnedsättning för med sig — för vuxna, eller för föräldrar till barn med funktionsnedsättning.', 'Compensation for the extra costs that a lasting disability brings — for adults, or for parents of children with disabilities.', '2026-09-03 21:22:47.145935+00'),
	('631e98cc-6ea0-4d99-ba5d-f17307ba3986', 'en', 'Ersättning för unga (19–29 år) som inte kan arbeta heltid under minst ett år på grund av sjukdom eller funktionsnedsättning.', 'Compensation for young people (19–29) who cannot work full-time for at least a year due to illness or disability.', '2026-09-03 21:22:47.145935+00'),
	('668d6222-bf55-4fcf-92e2-7b6850a617b9', 'en', 'Ersättning när arbetsförmågan är stadigvarande nedsatt — det som tidigare kallades förtidspension.', 'Compensation when your ability to work is permanently reduced — previously known as förtidspension (early retirement pension).', '2026-09-03 21:22:47.145935+00'),
	('62f32c2b-4dee-4e6e-8ead-3c2f6e768282', 'en', 'Ersättning när du avstår från arbete för att vara nära en svårt sjuk närstående.', 'Compensation when you refrain from work to be close to a seriously ill relative.', '2026-09-03 21:22:47.145935+00'),
	('b95f64d1-9745-4979-98f6-e106d59f444e', 'en', 'Ersättning när du deltar i ett arbetsmarknadspolitiskt program hos Arbetsförmedlingen.', 'Compensation when you take part in a labour market programme at Arbetsförmedlingen.', '2026-09-03 21:22:47.145935+00'),
	('4492e627-ad14-48d2-af71-98ac9eabd866', 'en', 'Ersättning när du inte kan arbeta som vanligt på grund av sjukdom.', 'Compensation when you cannot work as usual due to illness.', '2026-09-03 21:22:47.145935+00'),
	('22bd5af5-e523-46fd-8071-6a0f842e929f', 'en', 'Ersättning när du stannar hemma från arbetet för att ta hand om ett sjukt barn.', 'Compensation when you stay home from work to care for a sick child.', '2026-09-03 21:22:47.145935+00'),
	('62f1fe55-5bf3-423e-81e3-d53c0fefb85d', 'en', 'Ersättning som täcker en del av boendekostnaden för hushåll med barn och lägre inkomster.', 'Compensation covering part of the housing cost for households with children and lower incomes.', '2026-09-03 21:22:47.145935+00'),
	('fd50425c-dd88-4582-ada1-bdff8dc4933f', 'en', 'Ersättning till föräldrar vars barn på grund av funktionsnedsättning behöver mer omvårdnad och tillsyn än barn i samma ålder.', 'Compensation for parents whose children, due to disability, need more care and supervision than children of the same age.', '2026-09-03 21:22:47.145935+00'),
	('5fc18add-970c-4097-b471-7a9ef422c55e', 'en', 'Ersättning vid arbetslöshet — inkomstbaserad för medlemmar, grundbelopp för övriga.', 'Compensation during unemployment — income-based for members, a basic amount for others.', '2026-09-03 21:22:47.145935+00'),
	('bde0f55c-a66a-4a97-9c0f-aa50418a2f31', 'en', 'Ersättningen gäller privatpersoner', 'The benefit is for private individuals', '2026-09-03 21:22:47.145935+00'),
	('a5530991-13e6-4ce9-b707-a83cef98d90e', 'en', 'Ersättningen söks av privatpersoner', 'The benefit is applied for by private individuals', '2026-09-03 21:22:47.145935+00'),
	('44305182-024d-4e2c-9453-638caa7fa6ae', 'en', 'Ersättningen är aktuell vid varaktig sjukdom eller funktionsnedsättning', 'The benefit is relevant in the case of lasting illness or disability', '2026-09-03 21:22:47.145935+00'),
	('404a464f-9b93-40e2-bbb9-2da86f503d02', 'en', 'ESF bedömer kopplingen till arbetsmarknadens behov — konkret kompetensgap, inte allmän utbildning.', 'ESF assesses the link to the labour market''s needs — a concrete skills gap, not general training.', '2026-09-03 21:22:47.145935+00'),
	('daff8d0f-e9e8-4e82-a828-ae92711a09fd', 'en', 'ESF betalar ut i efterskott mot redovisning — likviditeten måste bära projektet under tiden.', 'ESF pays in arrears against reporting — your cash flow must carry the project in the meantime.', '2026-09-03 21:22:47.145935+00'),
	('4be11151-f7ad-4153-99f0-4855f388870b', 'en', 'Etableringen', 'Establishing yourself', '2026-09-03 21:22:47.145935+00'),
	('ba0679cb-2cb9-444e-9d51-db8709bb2f3e', 'en', 'Etableringsprogrammet förutsätter inskrivning — börja där om du inte redan är inskriven.', 'The establishment programme presupposes registration — start there if you are not already registered.', '2026-09-03 21:22:47.145935+00'),
	('9a711209-7207-4b36-a7ea-9889fb466193', 'en', 'Ett avgränsat projekt med tydlig början och slut — stiftelsen finansierar inte löpande verksamhet.', 'A defined project with a clear beginning and end — the foundation does not fund ongoing operations.', '2026-09-03 21:22:47.145935+00'),
	('8da3a4c8-4a25-4954-98a7-391d1ee7161e', 'en', 'Ett etablerat partnerskap i mållandet är kärnan i programmet.', 'An established partnership in the destination country is the core of the programme.', '2026-09-03 21:22:47.145935+00'),
	('8fe2e258-1d25-4d67-ac96-be6240e36659', 'en', 'Ett femtiotal sparbanksstiftelser delar ut bidrag till lokala projekt inom idrott, kultur, utbildning och samhällsutveckling — i sparbankens verksamhetsområde.', 'Some fifty savings bank foundations award grants to local projects in sports, culture, education and community development — within the savings bank''s area of operation.', '2026-09-03 21:22:47.145935+00'),
	('66bd05da-25a8-488b-9526-e1d65d0f957f', 'en', 'EU-ansökan som planeras', 'The planned EU application', '2026-09-03 21:22:47.145935+00'),
	('4e823700-041c-44fa-86ad-07fc07e067fb', 'en', 'EU-finansierat projektstöd som söks hos ditt lokala leaderområde — för föreningar, företag och kommuner som utvecklar landsbygden.', 'EU-funded project support applied for through your local Leader area — for associations, companies and municipalities developing rural areas.', '2026-09-03 21:22:47.145935+00'),
	('fe750227-d677-4648-9a72-8fdd93c67959', 'en', 'EU-finansierat stöd för arbetssökande som tar jobb i ett annat EU-/EES-land: ersättning för intervjuresa, flyttkostnader och språkkurs.', 'EU-funded support for jobseekers taking a job in another EU/EEA country: compensation for interview travel, moving costs and language courses.', '2026-09-03 21:22:47.145935+00'),
	('510377c6-13e6-4ead-bedb-ef6740a0c0b3', 'en', 'EU-socialfondsmedel för projekt som stärker kompetens, omställning och inkludering på arbetsmarknaden.', 'EU social fund money for projects that strengthen skills, transition and inclusion in the labour market.', '2026-09-03 21:22:47.145935+00'),
	('cc086539-da70-4118-908a-2ace4728dcaf', 'en', 'EU-stöd för grupputbyten för unga 13–30 år, 5–21 dagar exklusive resdagar.', 'EU support for group exchanges for young people aged 13–30, lasting 5–21 days excluding travel days.', '2026-09-03 21:22:47.145935+00'),
	('04ad6e71-d5be-42ff-98cb-121825f87d38', 'en', 'EU-stöd för kulturorganisationers samarbetsprojekt med partner i flera europeiska länder.', 'EU support for cultural organisations'' cooperation projects with partners in several European countries.', '2026-09-03 21:22:47.145935+00'),
	('27875053-fdb6-4e6d-849d-7274b6df6123', 'en', 'EU-stöd för organisationer som tar emot eller sänder unga volontärer 18–30 år.', 'EU support for organisations receiving or sending young volunteers aged 18–30.', '2026-09-03 21:22:47.145935+00'),
	('724bab54-d95d-40fd-8b32-b0b59e4a8c1a', 'en', 'EU-stöd för personal- och elevmobilitet inom skola och vuxenutbildning.', 'EU support for staff and pupil mobility in schools and adult education.', '2026-09-03 21:22:47.145935+00'),
	('ef0aedc4-6f3f-4f1d-943c-8ac5300e9663', 'en', 'EU-stöd med schablonbelopp för mindre organisationers första europeiska samarbetsprojekt.', 'EU support with lump sums for smaller organisations'' first European cooperation projects.', '2026-09-03 21:22:47.145935+00'),
	('9121a690-64c7-46a9-a726-277465160483', 'en', 'Extern leverantör/konsult (om känd)', 'External supplier/consultant (if known)', '2026-09-03 21:22:47.145935+00'),
	('3b3f67fd-df55-408d-9e64-af60ceef64c9', 'en', 'Filmen', 'The film', '2026-09-03 21:22:47.145935+00'),
	('f7ed385c-0fff-4bc9-bc38-cd5746b1acce', 'en', 'Filmens arbetstitel', 'Working title of the film', '2026-09-03 21:22:47.145935+00'),
	('652e6ccc-c95b-4ba7-97ee-9b5897eb6c5d', 'en', 'Finansiering för unga bolag som utvecklar nyskapande produkter eller tjänster med internationell potential.', 'Funding for young companies developing innovative products or services with international potential.', '2026-09-03 21:22:47.145935+00'),
	('e7948646-24b0-4001-ab71-cf863bff619d', 'en', 'Finns avtal eller dom om underhållsbidrag?', 'Is there an agreement or a court decision on maintenance?', '2026-09-03 21:22:47.145935+00'),
	('ed33c234-e70a-4c9a-916d-0e751c8494ff', 'en', 'Finns det en sparbank (och därmed en sparbanksstiftelse) där ni bedriver er verksamhet?', 'Is there a savings bank (and thus a savings bank foundation) where you operate?', '2026-09-03 21:22:47.145935+00'),
	('49992766-5bae-4dbe-96a7-8148a2b641c4', 'en', 'Finns en inbjudan eller bekräftelse från mottagande part?', 'Is there an invitation or confirmation from the receiving party?', '2026-09-03 21:22:47.145935+00'),
	('15b2cd41-bf53-41db-b41b-7eaa2729f939', 'en', 'Finns en skriftlig affärsplan?', 'Is there a written business plan?', '2026-09-03 21:22:47.145935+00'),
	('4ffd9036-23cc-4ada-a134-455ec8c0f3c2', 'en', 'Finns ett aktuellt läkarintyg eller läkarutlåtande?', 'Is there a current medical certificate or doctor''s statement?', '2026-09-03 21:22:47.145935+00'),
	('7edd60a9-8032-4af0-835a-02c10317e2fa', 'en', 'Finns ett läkarutlåtande om barnets funktionsnedsättning?', 'Is there a doctor''s statement about the child''s disability?', '2026-09-03 21:22:47.145935+00'),
	('5ceb6ba2-bdb5-4fdb-b9a7-f89b95d19b97', 'en', 'Finns ett läkarutlåtande om den närståendes tillstånd?', 'Is there a doctor''s statement about the relative''s condition?', '2026-09-03 21:22:47.145935+00'),
	('d04a6ccd-c4db-47da-9ba5-aea3d951db66', 'en', 'Finns ett läkarutlåtande om funktionsnedsättningen?', 'Is there a doctor''s statement about the disability?', '2026-09-03 21:22:47.145935+00'),
	('d0e23443-9aeb-4108-86bf-04674872affa', 'en', 'Finns intyg från arbetsterapeut, läkare eller annan sakkunnig?', 'Is there a certificate from an occupational therapist, doctor or other expert?', '2026-09-03 21:22:47.145935+00'),
	('c63a5cee-c405-4086-b6b1-85df32bf6bda', 'en', 'Finns ordination eller recept från optiker/ögonläkare?', 'Is there a prescription from an optician or ophthalmologist?', '2026-09-03 21:22:47.145935+00');
INSERT INTO public.kb_translations VALUES
	('e32a09e0-8649-4519-9372-8e5b56cbdf39', 'en', 'Fleråriga verksamhetsbidrag till professionella fria grupper inom dans, teater och musikteater.', 'Multi-year operating grants for professional independent groups in dance, theatre and musical theatre.', '2026-09-03 21:22:47.145935+00'),
	('b0456d1d-87ca-40ca-aac4-e5e49a82808f', 'en', 'Fonden kräver samarbete mellan flera nordiska länder — ange de länder som har en aktiv roll.', 'The fund requires cooperation between several Nordic countries — state the countries that have an active role.', '2026-09-03 21:22:47.145935+00'),
	('b2b1f588-a13e-4010-b3e8-f959222fd789', 'en', 'Formell sökande är en kommun (föreningar deltar via kommunen)', 'The formal applicant is a municipality (associations take part through the municipality)', '2026-09-03 21:22:47.145935+00'),
	('2fdc37bd-d9f8-4132-b1d2-6f56bd9b3461', 'en', 'Formulera som förändring för målgruppen, inte som aktiviteter.', 'Frame it as change for the target group, not as activities.', '2026-09-03 21:22:47.145935+00'),
	('8733f3b1-25c4-4fe0-a988-bebdb2a7f8ba', 'en', 'Forskaren', 'The researcher', '2026-09-03 21:22:47.145935+00'),
	('56bcf31f-ff3b-4f09-8297-48c38a2e71a6', 'en', 'Forskningsbidrag inom Fortes ansvarsområden: hälsa, arbetsliv och välfärd. Söks av disputerade forskare vid svenska lärosäten.', 'Research grants within Forte''s areas of responsibility: health, working life and welfare. Applied for by researchers with a doctorate at Swedish higher education institutions.', '2026-09-03 21:22:47.145935+00'),
	('2df808ee-c416-456c-af39-ff77154a7d5d', 'en', 'Forskningsmedel för fri grundforskning inom alla vetenskapsområden.', 'Research funding for free basic research in all scientific fields.', '2026-09-03 21:22:47.145935+00'),
	('228c87e4-cf8b-4093-91ef-20c33e0f59d1', 'en', 'Forskningsmedel inom miljö, areella näringar och samhällsbyggande.', 'Research funding within the environment, agricultural sciences and spatial planning.', '2026-09-03 21:22:47.145935+00'),
	('850516fe-8a4e-48d2-86c9-b3c5f7991e94', 'en', 'Forskningsplan', 'Research plan', '2026-09-03 21:22:47.145935+00'),
	('3fd56244-8e89-4476-8615-295db8c90af5', 'en', 'Forskningsplanen', 'The research plan', '2026-09-03 21:22:47.145935+00'),
	('f8a24c23-dd1c-4362-ac86-cf16ce8169a9', 'en', 'Forskningsplanens kärna', 'The core of the research plan', '2026-09-03 21:22:47.145935+00'),
	('a180dfc6-2bef-45f0-a14f-98716bdb3039', 'en', 'Forskningsprojektet', 'The research project', '2026-09-03 21:22:47.145935+00'),
	('8b86d4cc-516d-4e75-84de-6e2429d0391b', 'en', 'Fristående skola och folkhögskola → CSN. Kommunal skola → hemkommunen.', 'Independent school and folk high school → CSN. Municipal school → your home municipality.', '2026-09-03 21:22:47.145935+00'),
	('f5fb7ba9-01af-48d3-8b7b-47dd4d76c578', 'en', 'Frågeställning, metod och förväntade resultat — sakkunniggranskningen bedömer originalitet och genomförbarhet.', 'Research question, method and expected results — peer review assesses originality and feasibility.', '2026-09-03 21:22:47.145935+00'),
	('6f775ba2-57a8-44d2-9974-cc37115646c6', 'en', 'Frågeställning, metod och relevans för hälsa, arbetsliv eller välfärd — sakligt och prövbart.', 'Research question, method and relevance to health, working life or welfare — factual and testable.', '2026-09-03 21:22:47.145935+00'),
	('a1b80285-84f7-461a-81fc-59e2f3d96cb5', 'en', 'Funderar du på att flytta utomlands (för jobb, studier eller återvandring)?', 'Are you thinking about moving abroad (for work, studies or return migration)?', '2026-09-03 21:22:47.145935+00'),
	('454e02d0-fe1a-405f-8fb2-29cbcaae933a', 'en', 'Funktionsnedsättningen ska medföra merkostnader över lägstanivån', 'The disability must give rise to extra costs above the lowest level', '2026-09-03 21:22:47.145935+00'),
	('8fbe22c7-d663-4f85-a9b0-8b57ae26d770', 'en', 'Funktionsnedsättningen ska vara varaktig', 'The disability must be lasting', '2026-09-03 21:22:47.145935+00'),
	('5d5f99c8-c0cf-46f8-998e-4aeb3c2cac0b', 'en', 'Färdvägen kvalificerar (längd, trafik eller funktionsnedsättning — kommunens bedömning)', 'The journey qualifies (length, traffic or disability — the municipality decides)', '2026-09-03 21:22:47.145935+00'),
	('6db27f33-8bf0-4bb7-8208-46b2149c4fa0', 'en', 'Färdvägen till skolan är minst sex kilometer', 'The journey to school is at least six kilometres', '2026-09-03 21:22:47.145935+00'),
	('e72fc1fb-b1ca-4354-a18c-dbf0e6472767', 'en', 'Föreningen', 'The association', '2026-09-03 21:22:47.145935+00'),
	('5418bcb6-445c-4025-9c9f-5a16290a35cb', 'en', 'Föreningen ska bedriva regelbunden verksamhet i kommunen', 'The association must run regular activities in the municipality', '2026-09-03 21:22:47.145935+00'),
	('e5b38b75-b191-42b1-a83a-f8b72e423d2e', 'en', 'Föreningen ska vara ansluten till ett specialidrottsförbund inom RF', 'The association must be affiliated to a national sports federation within RF', '2026-09-03 21:22:47.145935+00'),
	('63856d06-1a8c-4d07-b1cd-39308e4d85ba', 'en', 'Föreningen ska vara demokratiskt uppbyggd med stadgar och styrelse', 'The association must be democratically structured, with statutes and a board', '2026-09-03 21:22:47.145935+00'),
	('fc53d09e-e4ab-4887-ac43-92beb5d14883', 'en', 'Föreningen ska vara verksam i Sverige', 'The association must be active in Sweden', '2026-09-03 21:22:47.145935+00'),
	('f765915d-5bff-41c0-9fa2-534cdb141c6f', 'en', 'Föreningens namn', 'Name of the association', '2026-09-03 21:22:47.145935+00'),
	('6695b209-5266-4fe0-a585-f61f7fb246cb', 'en', 'Föreningens stadgar', 'The association''s statutes', '2026-09-03 21:22:47.145935+00'),
	('8802d7e0-47de-45d4-bfc9-83c061c626f5', 'en', 'Föreningens/kommunens namn', 'Name of the association or municipality', '2026-09-03 21:22:47.145935+00'),
	('a414e355-d181-4139-8eb4-a7680495c270', 'en', 'Föreningens/stiftelsens namn', 'Name of the association or foundation', '2026-09-03 21:22:47.145935+00'),
	('ef9cfd2b-b44b-4613-a4a5-86e5a8782632', 'en', 'Företaget', 'The company', '2026-09-03 21:22:47.145935+00'),
	('51abb1ac-5b5c-4cf1-a85d-800a47e0bdff', 'en', 'Företaget du startar eller tar över', 'The business you are starting or taking over', '2026-09-03 21:22:47.145935+00'),
	('9eac1cca-559e-4869-a1db-0e049db0c0ba', 'en', 'Företaget ska vara litet (typiskt 2–49 anställda — se regionens villkor)', 'The company must be small (typically 2–49 employees — see the region''s terms)', '2026-09-03 21:22:47.145935+00'),
	('ac766a9a-2a40-467d-be21-b5984373c43e', 'en', 'Företaget ska vara registrerat i Sverige', 'The company must be registered in Sweden', '2026-09-03 21:22:47.145935+00'),
	('aa9f1a17-70cf-4834-826f-08e97dc484bb', 'en', 'Företagets namn', 'Name of the company', '2026-09-03 21:22:47.145935+00'),
	('86908a70-e53b-430f-9818-527e4bdd9339', 'en', 'Förflyttningsbehovet', 'The need to get around', '2026-09-03 21:22:47.145935+00'),
	('6cad624a-e804-4f18-bcae-13fdaf7c1302', 'en', 'Förlaget', 'The publisher', '2026-09-03 21:22:47.145935+00'),
	('5d9fb106-5eac-4325-8f28-1a1e57489ee6', 'en', 'Förlagets namn', 'Name of the publisher', '2026-09-03 21:22:47.145935+00'),
	('dffe2bbc-c225-416e-9b14-5a6adfa8a6a4', 'en', 'Föräldrarna ska inte bo tillsammans', 'The parents must not live together', '2026-09-03 21:22:47.145935+00'),
	('e63b8c2a-c595-431d-a111-a84c80706ccc', 'en', 'Garantipension lämnas från riktåldern (67 år från 2026)', 'Garantipension is granted from the reference age (67 from 2026)', '2026-09-03 21:22:47.145935+00'),
	('0be774d9-b42e-4f6d-ab3e-cba96da01c0d', 'en', 'Genomförs insatserna av professionella kulturaktörer?', 'Are the activities carried out by professional cultural actors?', '2026-09-03 21:22:47.145935+00'),
	('b6f2a0d1-b99f-4cfa-9e3c-105ea9aa17ee', 'en', 'Genomförs projektet på landsbygden eller i en mindre tätort?', 'Is the project carried out in a rural area or a smaller town?', '2026-09-03 21:22:47.145935+00'),
	('a8b55ae7-03ed-4fb0-a004-a8729e4f83c0', 'en', 'Grundskole- eller gymnasienivå, t.ex. komvux.', 'Compulsory-school or upper-secondary level, e.g. komvux (municipal adult education).', '2026-09-03 21:22:47.145935+00'),
	('6bf76f70-5e64-4894-91cc-92e7a782b165', 'en', 'Grundskydd för den som haft låg eller ingen arbetsinkomst under livet.', 'Basic protection for those who have had little or no earned income during their life.', '2026-09-03 21:22:47.145935+00'),
	('32a660f3-f0a6-4653-a82e-b5d658f6fe49', 'en', 'Gruppen/organisationen', 'The group or organisation', '2026-09-03 21:22:47.145935+00'),
	('66c29853-c763-46a8-9717-6aa891f9d348', 'en', 'Gruppens/organisationens namn', 'Name of the group or organisation', '2026-09-03 21:22:47.145935+00'),
	('0d276c41-760a-4434-aee6-61eec2e31cc3', 'en', 'Gränsen är normalt sex kilometer närmaste väg.', 'The limit is normally six kilometres by the shortest route.', '2026-09-03 21:22:47.145935+00'),
	('057c3130-95c3-4151-98cd-592c7a554d74', 'en', 'Gränsöverskridande samarbete', 'Cross-border cooperation', '2026-09-03 21:22:47.145935+00'),
	('be09740d-7c41-471b-b218-e45f16bcdce4', 'en', 'Gymnasieskolans namn och ort', 'Name and location of the upper-secondary school', '2026-09-03 21:22:47.145935+00'),
	('cae57647-6b8b-43fa-be10-6b67ed428bb6', 'en', 'Går något av dina barn i grundskolan?', 'Is any of your children in compulsory school?', '2026-09-03 21:22:47.145935+00'),
	('3dabd5a9-bd46-4da4-8a9e-667b8914e664', 'en', 'Går något av dina barn på gymnasiet?', 'Is any of your children in upper secondary school?', '2026-09-03 21:22:47.145935+00');
INSERT INTO public.kb_translations VALUES
	('6e5d3056-9a92-494f-9c45-1d6964122929', 'en', 'Gäller anställningen en person med nedsatt arbetsförmåga?', 'Does the employment concern a person with reduced work capacity?', '2026-09-03 21:22:47.145935+00'),
	('587155ca-37fa-4c3d-9d6c-ad4011d13098', 'en', 'Gäller anställningen någon som varit arbetslös länge eller är ny i Sverige?', 'Does the employment concern someone who has been unemployed for a long time or is new in Sweden?', '2026-09-03 21:22:47.145935+00'),
	('a565b868-ba39-441f-8238-344eabbf0ec8', 'en', 'Gäller ansökan ett barn du är vårdnadshavare för?', 'Does the application concern a child you are the guardian of?', '2026-09-03 21:22:47.145935+00'),
	('80d79b64-739c-4a8c-822d-baef6c910f88', 'en', 'Gäller elever folkbokförda i Sverige', 'Applies to pupils registered as resident in Sweden', '2026-09-03 21:22:47.145935+00'),
	('1b62c198-8885-4033-a20d-3bac1379d382', 'en', 'Gäller från och med det andra barnet du får barnbidrag för', 'Applies from the second child for whom you receive barnbidrag', '2026-09-03 21:22:47.145935+00'),
	('42a835f0-adcb-474a-9d3e-b407b33f7cf3', 'en', 'Gäller privatpersoner', 'Applies to private individuals', '2026-09-03 21:22:47.145935+00'),
	('b79bb396-9b25-45d8-98a2-83217fb8887d', 'en', 'Gäller vård i Sverige', 'Applies to care in Sweden', '2026-09-03 21:22:47.145935+00'),
	('8547f54f-7dc1-47bd-9b6f-b9f8026345c6', 'en', 'Handlar projektet om att bevara eller tillgängliggöra kulturarv?', 'Is the project about preserving or making cultural heritage accessible?', '2026-09-03 21:22:47.145935+00'),
	('daae00b3-1e11-4a85-9544-02d1805ee5c7', 'en', 'Handlar projektet om energi, energieffektivisering eller energirelaterad innovation?', 'Is the project about energy, energy efficiency or energy-related innovation?', '2026-09-03 21:22:47.145935+00'),
	('0f31af06-4dfc-48f0-b87e-1473f2b9a67a', 'en', 'Handlar projektet om hälsa, arbetsliv eller välfärd?', 'Is the project about health, working life or welfare?', '2026-09-03 21:22:47.145935+00'),
	('4eb02beb-0e6a-4e75-b9ad-53b87973dda9', 'en', 'Handlar projektet om kompetensutveckling eller arbetsmarknadsinsatser?', 'Is the project about skills development or labour market measures?', '2026-09-03 21:22:47.145935+00'),
	('0fc96b05-9f9e-4460-9ca8-f8eee818905a', 'en', 'Handlar projektet om miljö- eller klimatåtgärder?', 'Is the project about environmental or climate measures?', '2026-09-03 21:22:47.145935+00'),
	('0c997bea-ec07-4202-8f6d-3664129c6a51', 'en', 'Har barnet lång, trafikfarlig eller på annat sätt besvärlig väg till skolan?', 'Does the child have a long, traffic-hazardous or otherwise difficult route to school?', '2026-09-03 21:22:47.145935+00'),
	('29d5d623-d8ef-4508-852b-26fa33dfe4ce', 'en', 'Har den sjuke samtyckt till ansökan?', 'Has the person who is ill consented to the application?', '2026-09-03 21:22:47.145935+00'),
	('43f12cc6-57c7-4bde-a6d8-392cf28b6145', 'en', 'Har du (eller den som ska köra) körkort?', 'Do you (or the person who will drive) hold a driving licence?', '2026-09-03 21:22:47.145935+00'),
	('d57e1b31-ec36-4af7-a1e8-542a2a5a40fd', 'en', 'Har du arbetat minst 16 timmar i veckan i sammanlagt minst 8 år?', 'Have you worked at least 16 hours a week for a total of at least 8 years?', '2026-09-03 21:22:47.145935+00'),
	('ae5cf385-9c6c-4185-a19b-3730a14700f5', 'en', 'Har du barn som bor hos dig, helt eller växelvis?', 'Do you have children living with you, full-time or alternately?', '2026-09-03 21:22:47.145935+00'),
	('3daad4d9-ca69-484b-a5fd-79156f99f492', 'en', 'Har du barn som bor hos dig?', 'Do you have children living with you?', '2026-09-03 21:22:47.145935+00'),
	('cae210ba-de87-4c11-a257-b8df928bf184', 'en', 'Har du doktorsexamen?', 'Do you hold a doctoral degree?', '2026-09-03 21:22:47.145935+00'),
	('92c70745-27fe-4bea-aeeb-2870bdde77bf', 'en', 'Har du eller ditt barn en funktionsnedsättning som väntas bestå i minst ett år?', 'Do you or your child have a disability expected to last at least a year?', '2026-09-03 21:22:47.145935+00'),
	('033ef454-980f-4d2a-851e-84e876b0dbbb', 'en', 'Har du eller någon i hushållet en bestående funktionsnedsättning som påverkar boendet?', 'Do you or anyone in the household have a lasting disability that affects your housing?', '2026-09-03 21:22:47.145935+00'),
	('b1f47499-0477-4730-b486-2bcdedb807c7', 'en', 'Har du eller någon nära anhörig en funktionsnedsättning eller en långvarig eller allvarlig sjukdom?', 'Do you or a close relative have a disability or a long-term or serious illness?', '2026-09-03 21:22:47.145935+00'),
	('e1a93a72-6562-4ec3-a013-87035d96c28e', 'en', 'Har du en inbjudan eller bekräftelse från mottagande part?', 'Do you have an invitation or confirmation from the receiving party?', '2026-09-03 21:22:47.145935+00'),
	('704e2f52-e16a-4899-aeaa-9c85e85578b9', 'en', 'Har du en sjukdom eller skada som just nu sätter ned din förmåga att arbeta?', 'Do you have an illness or injury that currently reduces your ability to work?', '2026-09-03 21:22:47.145935+00'),
	('ffe7ac0e-fb28-42fb-9642-7a60014f515c', 'en', 'Har du en skriftlig affärsplan?', 'Do you have a written business plan?', '2026-09-03 21:22:47.145935+00'),
	('84409d6b-1e76-40da-99ec-d4b6283217ae', 'en', 'Har du kontaktat hemkommunen om studiestartsstödet?', 'Have you contacted your home municipality about studiestartsstödet?', '2026-09-03 21:22:47.145935+00'),
	('0697eb3d-9fbf-4764-bde8-fb01382e13c9', 'en', 'Har du någon gång haft svårt att betala för en skolutflykt, klassresa eller fritidsaktivitet som ditt barn förväntas delta i?', 'Have you ever found it hard to pay for a school outing, class trip or leisure activity your child is expected to take part in?', '2026-09-03 21:22:47.145935+00'),
	('45d1944c-aba2-43a7-a653-f93bc58f6644', 'en', 'Har du sparade medel eller tillgångar över ungefär 100 000 kr?', 'Do you have savings or assets worth roughly more than 100 000 kr?', '2026-09-03 21:22:47.145935+00'),
	('dff3fe88-399d-462e-ae42-484580b41006', 'en', 'Har du sparade medel eller tillgångar?', 'Do you have savings or assets?', '2026-09-03 21:22:47.145935+00'),
	('90c5c1a6-9fca-4554-9e3b-23883536b057', 'en', 'Har du svårt att klara dig på din pension och dina övriga inkomster?', 'Do you find it hard to manage on your pension and your other income?', '2026-09-03 21:22:47.145935+00'),
	('264c6a58-fbee-4a5e-9553-b4b8e583350c', 'en', 'Har du under de senaste åren fått uppehållstillstånd i Sverige, t.ex. som skyddsbehövande eller som anhörig?', 'Have you been granted a residence permit in Sweden in recent years, e.g. as a person in need of protection or as a family member?', '2026-09-03 21:22:47.145935+00'),
	('47903273-4f6d-4036-aa08-c99a0fa7bdc4', 'en', 'Har du uppehållstillstånd i Sverige som flykting eller skyddsbehövande (eller är du nära anhörig till någon som har det)?', 'Do you have a residence permit in Sweden as a refugee or person in need of protection (or are you a close family member of someone who has)?', '2026-09-03 21:22:47.145935+00'),
	('31a50fae-a15c-47e1-a564-a06e01bd89ba', 'en', 'Har du uppnått riktåldern för pension (67 år 2026)?', 'Have you reached the target age for pension (67 in 2026)?', '2026-09-03 21:22:47.145935+00'),
	('e5b265f5-d62e-49cd-bc49-d4760d7707af', 'en', 'Har eleven studiehjälp från CSN?', 'Does the pupil receive studiehjälp from CSN?', '2026-09-03 21:22:47.145935+00'),
	('02fbac6a-04af-4022-99b5-fc383e2fd692', 'en', 'Har er organisation ett OID (Organisation ID) registrerat i EU:s Organisation Registration System?', 'Does your organisation have an OID (Organisation ID) registered in the EU''s Organisation Registration System?', '2026-09-03 21:22:47.145935+00'),
	('5cdd5c24-a3ac-4845-a7ec-e7c5a3285284', 'en', 'Har funktionsnedsättningen medfört extra kostnader — t.ex. hjälpmedel, resor, särskild kost eller slitage?', 'Has the disability led to extra costs — e.g. aids, travel, special diet or wear and tear?', '2026-09-03 21:22:47.145935+00'),
	('fefbe511-fcbc-4161-8d85-89f44ac7dc60', 'en', 'Har föreningen antagna stadgar och en vald styrelse?', 'Does the association have adopted statutes and an elected board?', '2026-09-03 21:22:47.145935+00'),
	('41122666-e726-4205-af27-7a11739ebe43', 'en', 'Har föreningen en demokratisk uppbyggnad (stadgar, årsmöte, styrelse)?', 'Does the association have a democratic structure (statutes, annual meeting, board)?', '2026-09-03 21:22:47.145935+00'),
	('092b2f28-ce88-4f59-a6db-130e27ea0f9a', 'en', 'Har föreningen regelbunden verksamhet för barn eller unga?', 'Does the association run regular activities for children or young people?', '2026-09-03 21:22:47.145935+00'),
	('684fbf27-c9a3-4752-984c-4fa74ba95a53', 'en', 'Har företaget mellan cirka 2 och 49 anställda?', 'Does the company have between roughly 2 and 49 employees?', '2026-09-03 21:22:47.145935+00'),
	('a059b641-0361-4f89-9137-aa535772ff85', 'en', 'Har företaget tagit emot försumbart stöd (de minimis) under de senaste tre åren?', 'Has the company received de minimis aid over the past three years?', '2026-09-03 21:22:47.145935+00'),
	('08cce097-4ed2-460c-98c7-35e17b71df17', 'en', 'Har hushållet sparade medel eller tillgångar som kan användas till försörjningen?', 'Does the household have savings or assets that could be used for its upkeep?', '2026-09-03 21:22:47.145935+00'),
	('4879c5fc-a2dc-4519-8b4f-5d05b3ccfadb', 'en', 'Har hushållet svårt att klara kostnaderna för mat, boende och det mest nödvändiga?', 'Does the household struggle to cover the costs of food, housing and the bare necessities?', '2026-09-03 21:22:47.145935+00'),
	('5d46290f-c2f3-4000-8a56-18dbdc07b6cc', 'en', 'Har lösningen internationell potential?', 'Does the solution have international potential?', '2026-09-03 21:22:47.145935+00'),
	('a059ac7f-ffe9-4967-a418-f593789a0f91', 'en', 'Har ni en bekräftad partnergrupp i ett annat land?', 'Do you have a confirmed partner group in another country?', '2026-09-03 21:22:47.145935+00'),
	('beb2d43e-ab25-4537-b695-2ae2531dfa41', 'en', 'Har ni en partnergrupp i ett annat land?', 'Do you have a partner group in another country?', '2026-09-03 21:22:47.145935+00'),
	('05154f9a-aaf1-4e5c-835b-755e0d618264', 'en', 'Har ni en partnerorganisation i ett annat europeiskt land?', 'Do you have a partner organisation in another European country?', '2026-09-03 21:22:47.145935+00'),
	('2d7ec084-9361-448f-a2f0-330ae06bcbe0', 'en', 'Har ni partner i minst tre olika europeiska länder?', 'Do you have partners in at least three different European countries?', '2026-09-03 21:22:47.145935+00'),
	('6c4b05b4-b1ed-4263-828a-d4d8caed4ebb', 'en', 'Har ni säte eller huvudsaklig verksamhet i den region där ni söker?', 'Is your registered office or main activity in the region where you are applying?', '2026-09-03 21:22:47.145935+00'),
	('0a2d9997-4503-4be4-9bb5-7fcdb3a7ef72', 'en', 'Har något av dina barn en funktionsnedsättning som gör att barnet behöver mer omvårdnad eller tillsyn än andra barn i samma ålder?', 'Does any of your children have a disability that means the child needs more care or supervision than other children of the same age?', '2026-09-03 21:22:47.145935+00');
INSERT INTO public.kb_translations VALUES
	('7c123809-9fcf-42cb-810e-a8deda31b030', 'en', 'Har organisationen en demokratisk uppbyggnad?', 'Does the organisation have a democratic structure?', '2026-09-03 21:22:47.145935+00'),
	('090f074c-0057-4b3b-b706-0aa2ef529410', 'en', 'Har organisationen en Quality Label (kvalitetsmärkning)?', 'Does the organisation have a Quality Label?', '2026-09-03 21:22:47.145935+00'),
	('013fc1c8-6cc9-4788-bacd-66e012639fc1', 'en', 'Har organisationen ett 90-konto?', 'Does the organisation have a 90-konto?', '2026-09-03 21:22:47.145935+00'),
	('fcf97a29-2e1b-40c4-be23-6bd6c9709a23', 'en', 'Har organisationen ett OID (Organisation ID)?', 'Does the organisation have an OID (Organisation ID)?', '2026-09-03 21:22:47.145935+00'),
	('01d76c74-d503-4e29-91c8-2704d4088001', 'en', 'Har organisationen ett OID?', 'Does the organisation have an OID?', '2026-09-03 21:22:47.145935+00'),
	('fa951d85-ec1d-4dc9-90dc-f2e1d64d4b20', 'en', 'Har organisationen giltig Quality Label?', 'Does the organisation hold a valid Quality Label?', '2026-09-03 21:22:47.145935+00'),
	('5f2a4ab4-7637-48b8-8c25-e475b82cce61', 'en', 'Har organisationen medlemsföreningar i flera län?', 'Does the organisation have member associations in several counties?', '2026-09-03 21:22:47.145935+00'),
	('39f98f97-a49a-4bce-aa45-f33583170f67', 'en', 'Har organisationen ordnad ekonomi och demokratisk struktur?', 'Does the organisation have sound finances and a democratic structure?', '2026-09-03 21:22:47.145935+00'),
	('e78213e6-1846-4c39-9ada-87357615ca85', 'en', 'Har projektet en partner i ett annat land?', 'Does the project have a partner in another country?', '2026-09-03 21:22:47.145935+00'),
	('bc057c6b-5116-4ad4-869c-d432dca34c92', 'en', 'Har projektledaren doktorsexamen?', 'Does the project leader have a doctoral degree?', '2026-09-03 21:22:47.145935+00'),
	('c8b06b90-9757-4d3d-8c13-22fe8771ecfe', 'en', 'Helt bidrag 12 333 kr/mån före skatt. Tre fjärdedels 9 250 kr, halvt 6 167 kr, en fjärdedels 3 083 kr.', 'Full benefit 12 333 kr/month before tax. Three quarters 9 250 kr, half 6 167 kr, one quarter 3 083 kr.', '2026-09-03 21:22:47.145935+00'),
	('1957c58e-de9b-4d63-a76d-e726b990a514', 'en', 'Hemkommunen ska stå för dagliga resor mellan bostad och gymnasieskola när färdvägen är minst sex kilometer (t.ex. busskort).', 'Your home municipality must provide daily travel between home and upper secondary school when the route is at least six kilometres (e.g. a bus pass).', '2026-09-03 21:22:47.145935+00'),
	('9afe1d1b-7ec1-4768-b239-5522e1a03fe4', 'en', 'Hur fungerar underhållet i dag?', 'How does the maintenance work today?', '2026-09-03 21:22:47.145935+00'),
	('0cd9c357-f9f5-4f80-85c0-c5d554e571e8', 'en', 'Hur försörjer du dig under uppstarten?', 'How will you support yourself during the start-up phase?', '2026-09-03 21:22:47.145935+00'),
	('4e365e91-a79f-436d-97d8-61f201299625', 'en', 'Hur klarar ni likviditeten tills stödet betalas ut?', 'How will you manage cash flow until the grant is paid out?', '2026-09-03 21:22:47.145935+00'),
	('98e61070-b720-428a-8d52-2a600d839c2c', 'en', 'Hur lever verksamheten vidare efter projektet?', 'How will the activity live on after the project?', '2026-09-03 21:22:47.145935+00'),
	('5ad5f817-9c3d-43d4-9e83-f24b9c71e35a', 'en', 'Hur ska stödet användas?', 'What will the support be used for?', '2026-09-03 21:22:47.145935+00'),
	('43e49f03-83ab-4616-baea-2587f2ae617f', 'en', 'Hur stärker projektet demokrati, yttrandefrihet eller mänskliga rättigheter genom kultur eller media? Mekanismen bedöms, inte avsikten.', 'How does the project strengthen democracy, freedom of expression or human rights through culture or media? The mechanism is assessed, not the intention.', '2026-09-03 21:22:47.145935+00'),
	('4a30cf13-df88-4bbd-820c-ad97b4aee014', 'en', 'Hur stärker utbildningen din ställning på arbetsmarknaden?', 'How does the training strengthen your position in the labour market?', '2026-09-03 21:22:47.145935+00'),
	('bbeea28e-b411-4a60-91dd-feda776c459b', 'en', 'Hur tar du tillvara erfarenheterna i Sverige?', 'How will you make use of what you learn back in Sweden?', '2026-09-03 21:22:47.145935+00'),
	('e36061e2-602c-40fc-9e7c-61f9e2fa59a2', 'en', 'Hur är målgruppen delaktig i planering och genomförande?', 'How is the target group involved in the planning and delivery?', '2026-09-03 21:22:47.145935+00'),
	('fce1c22b-6320-498b-bfd5-b5d3ecee18a7', 'en', 'Hushållet', 'The household', '2026-09-03 21:22:47.145935+00'),
	('748f1cfc-7a72-4f88-b464-1198c5780184', 'en', 'Hushållets beräknade inkomst i år, före skatt (kr)', 'The household''s estimated income this year, before tax (kr)', '2026-09-03 21:22:47.145935+00'),
	('8bb028ea-85bf-4f90-9c57-16ca4b0e8a79', 'en', 'Hushållets inkomst ska vara under inkomstgränsen', 'The household''s income must be below the income limit', '2026-09-03 21:22:47.145935+00'),
	('fe49d0d2-eae9-4b99-b583-3f84b5843a59', 'en', 'Hushållets inkomster per månad (kr)', 'The household''s income per month (kr)', '2026-09-03 21:22:47.145935+00'),
	('349d7831-26d6-4ef7-a2cd-af4fc38f4363', 'en', 'Huvudmannen', 'The principal organiser', '2026-09-03 21:22:47.145935+00'),
	('40407e0c-aa83-4f22-a5f0-06c9b155922e', 'en', 'Huvudmannens namn', 'Name of the principal organiser', '2026-09-03 21:22:47.145935+00'),
	('f4dac9c9-f947-471c-8351-2e5a4a8959f6', 'en', 'Hyra eller månadskostnad inklusive uppvärmning.', 'Rent or monthly cost including heating.', '2026-09-03 21:22:47.145935+00'),
	('48ddbda9-9e1e-4138-ad9e-b4e668126267', 'en', 'Hög andel unga medlemmar', 'A high share of young members', '2026-09-03 21:22:47.145935+00'),
	('92a22cb2-05af-44fe-b1e1-8cdf3d376ebf', 'en', 'Högst 1 259 kr/dag på sjukpenningnivå, lägst 250 kr/dag. Lägstanivådagar ger 180 kr/dag.', 'At most 1 259 kr/day at sjukpenningnivå (the sickness-benefit level), at least 250 kr/day. Days at the lowest level (lägstanivådagar) give 180 kr/day.', '2026-09-03 21:22:47.145935+00'),
	('1db81ead-a2d5-44b7-be3a-4c3b7afa4cdf', 'en', 'Högst 1 300 kr/mån. Kräver att årsinkomsten är högst 86 720 kr (103 720 kr tillsammans med make eller sambo) och att boendet kostar mer än 1 800 kr/mån.', 'At most 1 300 kr/month. Requires an annual income of at most 86 720 kr (103 720 kr together with a spouse or cohabiting partner) and housing costing more than 1 800 kr/month.', '2026-09-03 21:22:47.145935+00'),
	('f6b6cac2-2113-434e-82da-6f9e0581ea23', 'en', 'Idrottsverksamhet', 'Sports activities', '2026-09-03 21:22:47.145935+00'),
	('7b655d7b-533c-4f35-9e73-6a710d8de64a', 'es', 'Beskriv kulturinsatserna', 'Describe las actividades culturales', '2026-09-03 21:22:47.184972+00'),
	('b4b5547c-00c2-4097-b616-2cca3dbc7e09', 'en', 'Inbjudan eller bekräftelse från mottagande part', 'Invitation or confirmation from the receiving party', '2026-09-03 21:22:47.145935+00'),
	('6d471da0-4c02-41d3-82a0-8bbbdfea84b1', 'en', 'Inbjudan eller beskrivning av samarbetet', 'Invitation or description of the collaboration', '2026-09-03 21:22:47.145935+00'),
	('ce77079a-c209-4580-895f-2ec3a06533b2', 'en', 'Inbjudan väger tungt — utan den bedöms utbytet som oplanerat.', 'The invitation carries a lot of weight — without it the exchange is judged to be unplanned.', '2026-09-03 21:22:47.145935+00'),
	('a6ce1a9d-c345-495d-99b6-a5a6e7e66a29', 'en', 'Industriklivet finansierar åtgärder mot processutsläpp — kvantifiera minskningen i CO2-ekvivalenter och beskriv teknikens mognadsgrad.', 'Industriklivet funds measures against process emissions — quantify the reduction in CO2 equivalents and describe the technology''s maturity.', '2026-09-03 21:22:47.145935+00'),
	('f6019b8c-92cd-4bdb-9724-63e446919cb1', 'en', 'Ingen ansökan — registreras normalt automatiskt i regionens system; spara kvitton vid besök i annan region.', 'No application — it is normally registered automatically in the region''s system; keep your receipts when you visit another region.', '2026-09-03 21:22:47.145935+00'),
	('6075bf1d-aa82-4644-85b5-136f0c1c9947', 'en', 'Ingen ansökan — säg till hos tandvården att du vill använda bidraget.', 'No application — just tell the dental clinic that you want to use the allowance.', '2026-09-03 21:22:47.145935+00'),
	('2248371a-ef2e-4831-8373-16a83eeb6098', 'en', 'Ingår i ansökan om allmän pension hos Pensionsmyndigheten; prövas automatiskt.', 'It is included in the application for the general pension at Pensionsmyndigheten and is assessed automatically.', '2026-09-03 21:22:47.145935+00'),
	('a9d9c6b7-0424-46dc-94b4-44f1e1600474', 'en', 'Inkomster', 'Income', '2026-09-03 21:22:47.145935+00'),
	('e3017ef4-398d-4977-bd7c-fb37b428d599', 'en', 'Inkomsterna ska inte räcka till det mest nödvändiga', 'Your income must not be enough for the most essential needs', '2026-09-03 21:22:47.145935+00'),
	('2a0f577a-2097-4024-a930-94463b3a353a', 'en', 'Inkomsterna ska vara låga i förhållande till boendekostnaden', 'Your income must be low in relation to the housing cost', '2026-09-03 21:22:47.145935+00'),
	('7ddccedb-9ea1-46e0-91b5-24714c182482', 'en', 'Inköp av litteratur för barn och unga prioriteras; stödet får inte ersätta kommunens egen medieanslag — egeninsatsen ska bestå.', 'Purchases of literature for children and young people are prioritised; the grant must not replace the municipality''s own media budget — your own contribution must remain.', '2026-09-03 21:22:47.145935+00'),
	('e02bf8e9-6190-4747-a624-ddc5f2eb9354', 'en', 'Inköpen', 'The purchases', '2026-09-03 21:22:47.145935+00'),
	('a4fed8f7-df60-40a2-b6f3-7ddae31df1b8', 'en', 'Innehåller projektet en internationell resa eller ett internationellt utbyte?', 'Does the project include an international trip or exchange?', '2026-09-03 21:22:47.145935+00'),
	('345f45ec-d99e-404b-9d1c-4c5be3a30773', 'en', 'Inriktning (växtodling, djurhållning, trädgård, rennäring), omfattning och om du startar nytt eller tar över.', 'Focus (crop production, livestock, horticulture, reindeer husbandry), scale, and whether you are starting up or taking over.', '2026-09-03 21:22:47.145935+00'),
	('d0425f0a-5791-4d65-af55-1e25b1cf908a', 'en', 'Insatserna ska genomföras av professionella kulturaktörer', 'The activities must be delivered by professional cultural practitioners', '2026-09-03 21:22:47.145935+00'),
	('2d24b625-f97b-45b1-97e2-cad022371241', 'en', 'Internationaliseringsambition', 'Internationalisation ambition', '2026-09-03 21:22:47.145935+00'),
	('8a2109df-b30b-4e1c-9481-ba4ab43d8345', 'en', 'Internationell dimension', 'International dimension', '2026-09-03 21:22:47.145935+00');
INSERT INTO public.kb_translations VALUES
	('3e138453-30a9-408e-b681-f770beb7186e', 'en', 'Internationell skalbarhet', 'International scalability', '2026-09-03 21:22:47.145935+00'),
	('9207fb2f-fcb4-433e-a167-94b922d0359c', 'en', 'Intervjuresa, flyttkostnad, språkkurs eller erkännande av examen — beloppen är schabloner per insats. EURES-rådgivaren bekräftar vad som gäller din programperiod.', 'Interview trip, moving costs, language course or recognition of qualifications — the amounts are standard rates per measure. The EURES adviser confirms what applies to your programme period.', '2026-09-03 21:22:47.145935+00'),
	('f2c5ab1a-8a25-4754-aed6-c1a663025a37', 'en', 'Intyg', 'Certification', '2026-09-03 21:22:47.154334+00'),
	('d7afabfc-01c9-42b4-b8bd-61daa7fcbbfb', 'en', 'Intyg från arbetsterapeut, läkare eller motsvarande', 'A certificate from an occupational therapist, doctor or equivalent', '2026-09-03 21:22:47.154334+00'),
	('642a72e9-0d24-4afa-9d7f-353fa1d21aab', 'en', 'Investeringen', 'The investment', '2026-09-03 21:22:47.154334+00'),
	('a1f782ff-f1cd-4c22-a575-c53a85b88fd5', 'en', 'Investeringen får inte vara påbörjad före ansökan', 'The investment must not have begun before the application', '2026-09-03 21:22:47.154334+00'),
	('ce9a2a77-785a-46bc-8fbd-78faa2da1c30', 'en', 'Investeringen ska avse jordbruksverksamhet', 'The investment must concern agricultural activity', '2026-09-03 21:22:47.154334+00'),
	('f1c738dd-46e3-4709-b51e-81b67f6d4263', 'en', 'Investeringskalkyl', 'Investment calculation', '2026-09-03 21:22:47.154334+00'),
	('b7e5e474-91a0-45f5-a210-7f54154f3d54', 'en', 'Investeringskalkyl med offerter', 'Investment calculation with quotations', '2026-09-03 21:22:47.154334+00'),
	('a5160a1a-38cc-470f-be16-4ba011b0a27d', 'en', 'Investeringskostnad (kr)', 'Investment cost (kr)', '2026-09-03 21:22:47.154334+00'),
	('d01dfa5a-6945-473c-9380-bdc265865950', 'en', 'Investeringsstöd till företag i stödområden för byggnader, maskiner och utbildning.', 'Investment support for companies in designated support areas, for buildings, machinery and training.', '2026-09-03 21:22:47.154334+00'),
	('138751af-bfd5-4eef-b381-d82551cc9271', 'en', 'Investeringsstöd till åtgärder som minskar utsläppen av växthusgaser.', 'Investment support for measures that reduce greenhouse gas emissions.', '2026-09-03 21:22:47.154334+00'),
	('cc0d997d-b22b-4981-bceb-ec0c6c37a0f9', 'en', 'Jag intygar att investeringen inte påbörjas före ansökan', 'I certify that the investment will not begin before the application', '2026-09-03 21:22:47.154334+00'),
	('35ca2679-4a07-40b6-9ae7-2d4c9a596ecf', 'en', 'Jag intygar att investeringen inte påbörjats före ansökan', 'I certify that the investment has not begun before the application', '2026-09-03 21:22:47.154334+00'),
	('71690b93-4fc6-45ba-bec7-e8b8ab5c328b', 'en', 'Jag intygar att lämnade uppgifter är riktiga', 'I certify that the information provided is correct', '2026-09-03 21:22:47.154334+00'),
	('e810a4b3-1363-4a32-98a3-2b84e88e0d52', 'en', 'Jag intygar att åtgärden inte påbörjats före ansökan', 'I certify that the measure has not begun before the application', '2026-09-03 21:22:47.154334+00'),
	('2c74000e-2c54-44a4-afec-c7f8ca6d600c', 'en', 'Jobbet och flytten', 'The job and the move', '2026-09-03 21:22:47.154334+00'),
	('a543c44b-5d0e-4841-9dd3-ad949eeb9e4a', 'en', 'Jämför med barn i samma ålder: vad kräver mer tid, närvaro eller passning — dygnet runt-perspektivet räknas.', 'Compare with children of the same age: what demands more time, presence or supervision — the round-the-clock perspective counts.', '2026-09-03 21:22:47.154334+00'),
	('fc9dd61c-e29f-44ed-ac3a-460e215e2d3d', 'en', 'Kan organisationen förfinansiera kostnaderna?', 'Can the organisation pre-finance the costs?', '2026-09-03 21:22:47.154334+00'),
	('c8264d22-72db-4055-a190-8a7ecab5b596', 'en', 'Kan projektets miljönytta mätas?', 'Can the project''s environmental benefit be measured?', '2026-09-03 21:22:47.154334+00'),
	('f0fadbc5-b635-41a8-820c-961ca79e835d', 'en', 'Kan åtgärdens utsläppsminskning beräknas?', 'Can the measure''s emission reduction be calculated?', '2026-09-03 21:22:47.154334+00'),
	('7bcb5343-219b-4a98-a81a-ec15e1e422b3', 'en', 'Kapital påverkar bostadstilläggets storlek — att redovisa det öppet undviker återkrav.', 'Capital affects the size of bostadstillägget — declaring it openly avoids repayment demands.', '2026-09-03 21:22:47.154334+00'),
	('ce2bad52-859d-4bd9-a8ce-9cb6a962a597', 'en', 'Klarar organisationen att ligga ute med kostnader tills stödet betalas ut?', 'Can the organisation carry the costs until the support is paid out?', '2026-09-03 21:22:47.154334+00'),
	('44c00b07-aeb4-492d-bd27-54054a784538', 'en', 'Klimatklivet rangordnar på klimatnytta per investerad krona — utsläppsminskningen ska vara beräknad och beräkningen redovisbar.', 'Klimatklivet ranks applications by climate benefit per krona invested — the emission reduction must be calculated and the calculation must be presentable.', '2026-09-03 21:22:47.154334+00'),
	('5afd0071-bed9-4eae-ba67-0904185380c3', 'en', 'Klimatnyttan ska kunna beräknas', 'The climate benefit must be calculable', '2026-09-03 21:22:47.154334+00'),
	('9ddf211f-a5db-4b02-b330-ecf28905849a', 'en', 'Klimatåtgärden', 'The climate measure', '2026-09-03 21:22:47.154334+00'),
	('a40da786-931d-48c7-ba58-8aa1dd390294', 'es', 'Eleven och resvägen', 'El alumno y el trayecto', '2026-09-03 21:22:47.184972+00'),
	('913f538c-a305-4601-9309-54df4c276694', 'en', 'Kommer erfarenheterna att användas i din verksamhet i Sverige?', 'Will the experience be used in your activities in Sweden?', '2026-09-03 21:22:47.154334+00'),
	('aa8e9994-a90d-4a97-9bd1-285cca98b7e2', 'en', 'Kommer investeringen att påbörjas först efter att ni skickat in ansökan?', 'Will the investment start only after you have submitted the application?', '2026-09-03 21:22:47.154334+00'),
	('6fb4d5f0-67de-4c81-87a9-6f94d64aa1e0', 'en', 'Kommer projektet människor i ert närområde till del?', 'Does the project benefit people in your local area?', '2026-09-03 21:22:47.154334+00'),
	('4c5fafd1-a2bb-4a50-b0a2-4953ff4b9a6f', 'en', 'Kommun som står bakom ansökan', 'Municipality backing the application', '2026-09-03 21:22:47.154334+00'),
	('a2396009-3555-47e2-a9f9-3e750bff5239', 'en', 'Kommunen', 'The municipality', '2026-09-03 21:22:47.154334+00'),
	('e65b42ff-5f07-4f70-b9b1-5fa10ba71685', 'en', 'Kommunen ansöker via länsstyrelsen; föreningar initierar via sin kommun.', 'The municipality applies via the länsstyrelse; associations start the process through their municipality.', '2026-09-03 21:22:47.154334+00'),
	('a33c6ee0-d26f-4cb7-b3e4-7ca5fed7303a', 'en', 'Kommunen bedömer om du tillhör målgruppen innan CSN kan bevilja.', 'The municipality assesses whether you belong to the target group before CSN can approve.', '2026-09-03 21:22:47.154334+00'),
	('131ca867-6461-430a-8a53-7217782fcbe3', 'en', 'Kommunens avståndsgräns skiljer sig ofta per årskurs.', 'The municipality''s distance threshold often differs by school year.', '2026-09-03 21:22:47.154334+00'),
	('28c705ca-cf4c-4721-b534-fba02df6f7d1', 'en', 'Kommunens eget medieanslag i år (kr)', 'The municipality''s own media budget this year (kr)', '2026-09-03 21:22:47.154334+00'),
	('63faad3a-2166-4f1d-84ff-da564a0386c4', 'en', 'Kommunens namn', 'Name of the municipality', '2026-09-03 21:22:47.154334+00'),
	('0d65e0b8-fb75-4dfa-ba84-9c8d2bce4f8e', 'en', 'Kommunens yttersta ekonomiska skyddsnät när inkomsterna inte räcker till det mest nödvändiga.', 'The municipality''s last financial safety net when income does not cover the bare necessities.', '2026-09-03 21:22:47.154334+00'),
	('258825ca-7ae9-41e2-8257-bee92164a8be', 'en', 'Kommunernas egna stöd till det lokala föreningslivet: aktivitetsstöd per deltagartillfälle, lokalbidrag, startbidrag med mera.', 'The municipalities'' own support for the local association scene: activity support per session, premises grants, start-up grants and more.', '2026-09-03 21:22:47.154334+00'),
	('27696f93-0a2c-44b4-9585-48c0a0c9e38b', 'en', 'Kompetensinsatsen', 'The skills initiative', '2026-09-03 21:22:47.154334+00'),
	('33b08642-9310-4e6e-81df-2a83698a98a7', 'en', 'Konkret ur vardagen: trösklar, trappor, badrum. Intyg från arbetsterapeut eller läkare styrker behovet.', 'Be concrete about everyday life: thresholds, stairs, bathroom. A certificate from an occupational therapist or doctor supports the need.', '2026-09-03 21:22:47.154334+00'),
	('80d14733-bd64-4319-8c85-d902e698d4e8', 'en', 'Konkret: avståndet, en trafikfarlig passage, funktionsnedsättning eller växelvis boende. Kommunen prövar mot sina riktlinjer.', 'Be concrete: the distance, a dangerous crossing, a disability or alternating residence. The municipality assesses this against its own guidelines.', '2026-09-03 21:22:47.154334+00'),
	('0209fcd8-dc8f-43c8-98ff-fae4ccb2f454', 'en', 'Konkret: vad går inte, vad krävs för att det ska gå, och hur varaktigt är det?', 'Be concrete: what does not work, what is needed for it to work, and how lasting is it?', '2026-09-03 21:22:47.154334+00'),
	('b04c0d1a-099e-482c-83f3-805e86c04f8f', 'en', 'Konkret: vad har hänt, vad räcker inte pengarna till, och vad gör du själv för att förändra situationen?', 'Be concrete: what has happened, what the money is not enough for, and what you are doing yourself to change the situation.', '2026-09-03 21:22:47.154334+00'),
	('530e6825-d3cf-4ac7-a8b3-4ca131e81174', 'en', 'Konkret: vad händer i samarbetet som inte hade hänt nationellt?', 'Be concrete: what happens in the collaboration that would not have happened nationally?', '2026-09-03 21:22:47.154334+00'),
	('b43e6e55-0c08-498e-a164-bbebd20322f0', 'en', 'Konsert-/produktionsverksamhet', 'Concert or production activity', '2026-09-03 21:22:47.154334+00'),
	('761f7168-f31d-42dc-bdad-c4f2a3047012', 'en', 'Konsortiebyggande, ansökningsskrivning, resor — det bidraget faktiskt får användas till.', 'Consortium building, writing the application, travel — what the grant may actually be used for.', '2026-09-03 21:22:47.154334+00'),
	('c00e7999-6f42-4ca7-ba09-2632e2ac2d7f', 'en', 'Konstnärlig meritförteckning', 'Artistic record of merits', '2026-09-03 21:22:47.154334+00'),
	('f876bc67-8b9c-4090-ace7-fb216ce09274', 'en', 'Konstnärlig verksamhet', 'Artistic work', '2026-09-03 21:22:47.154334+00'),
	('5b15d157-59d7-4ee3-a91a-d11e1e9d7d0e', 'en', 'Konstnärligt projekt', 'Artistic project', '2026-09-03 21:22:47.154334+00');
INSERT INTO public.kb_translations VALUES
	('eafadbc6-4a0e-4d78-8a14-22c758ad7a45', 'en', 'Konstområde', 'Art form', '2026-09-03 21:22:47.154334+00'),
	('3e224ca2-695e-4e10-8510-529995fa4822', 'en', 'Kontakta ditt leaderområdes kansli; ansökan lämnas i Jordbruksverkets e-tjänst.', 'Contact the office of your Leader area; the application is submitted in Jordbruksverket''s e-service.', '2026-09-03 21:22:47.154334+00'),
	('bc8fa6dc-e9e2-41ad-87f6-e8dfcb19beec', 'en', 'Kontakta en EURES-rådgivare via Arbetsförmedlingen — ansökan görs innan flytten/resan.', 'Contact a EURES adviser through Arbetsförmedlingen — you apply before the move or the trip.', '2026-09-03 21:22:47.154334+00'),
	('47dfe115-9cc9-4c0f-8623-d59c5b5d83a3', 'en', 'Kontakta hemkommunen (målgruppsbedömning) och ansök därefter hos CSN.', 'Contact your home municipality (target-group assessment) and then apply at CSN.', '2026-09-03 21:22:47.154334+00'),
	('16d0fb07-ac7e-4393-a6fa-2e44a860380f', 'en', 'Kontrollera att utbildningen är godkänd för studiemedel i CSN:s tjänst INNAN du tackar ja till platsen.', 'Check in CSN''s service that the programme is approved for student finance BEFORE you accept the place.', '2026-09-03 21:22:47.154334+00'),
	('3dc61d42-21bf-4c6d-a5f2-6375c7b4f121', 'en', 'Koppla till leaderområdets utvecklingsstrategi — lokal förankring och samarbete väger tungt.', 'Connect it to the Leader area''s development strategy — local roots and cooperation carry a lot of weight.', '2026-09-03 21:22:47.154334+00'),
	('c4dc7806-ed22-4ad9-8f9a-c328320c1984', 'en', 'Kostnad för glasögon eller linser (kr)', 'Cost of glasses or contact lenses (kr)', '2026-09-03 21:22:47.154334+00'),
	('f523d917-f3e3-4ce0-bb56-d6dbdc3b9ad5', 'en', 'Kostnad och finansiering', 'Cost and financing', '2026-09-03 21:22:47.154334+00'),
	('2f6f8d3e-f0eb-4870-a828-010e93020f61', 'en', 'Kostnads- och finansieringsplan', 'Cost and financing plan', '2026-09-03 21:22:47.154334+00'),
	('d38cde51-4b74-47f5-9172-f54976f3aac5', 'en', 'Kostnadsfri skolskjuts för grundskoleelever vid långt avstånd, trafikfarlig väg eller funktionsnedsättning — en rättighet enligt skollagen.', 'Free school transport for compulsory school pupils in case of long distance, traffic-hazardous routes or disability — a right under the Education Act.', '2026-09-03 21:22:47.154334+00'),
	('89eed6ee-3f3f-423c-a629-3717e5264312', 'en', 'Kostnadskalkyl och finansieringsplan', 'Cost estimate and financing plan', '2026-09-03 21:22:47.154334+00'),
	('cb0637d7-98f5-4125-becd-9f87e0debc02', 'en', 'Kravet är i genomsnitt minst 16 timmar i veckan under minst 8 år.', 'The requirement is an average of at least 16 hours a week for at least 8 years.', '2026-09-03 21:22:47.154334+00'),
	('5e049d13-07ff-4145-8d48-579a84f56a6e', 'en', 'Kravet är minst 60 % — medlemsregistret är underlaget och MUCF granskar det.', 'The requirement is at least 60 % — the membership register is the evidence and MUCF reviews it.', '2026-09-03 21:22:47.154334+00'),
	('423c9753-f9ba-420b-a67b-98c1ab393933', 'en', 'Kultur/media som verktyg', 'Culture or media as a tool', '2026-09-03 21:22:47.154334+00'),
	('1729cd34-3d81-4e82-99fa-5cf957379ffd', 'en', 'Kulturbryggan finansierar det oprövade — beskriv vad som skiljer projektet från befintlig praxis, inte bara att det är nytt för er.', 'Kulturbryggan funds the untried — describe what sets the project apart from existing practice, not merely that it is new to you.', '2026-09-03 21:22:47.154334+00'),
	('2e9265d7-3bcf-42f2-92ea-daa7ee8d850e', 'en', 'Kulturbryggan ser gärna fler finansieringskällor — redovisa öppet vad som är sökt respektive beviljat.', 'Kulturbryggan welcomes several funding sources — declare openly what has been applied for and what has been granted.', '2026-09-03 21:22:47.154334+00'),
	('35585aaf-e614-4af5-b29c-58cf44c6b151', 'en', 'Kulturinsatserna', 'The cultural activities', '2026-09-03 21:22:47.154334+00'),
	('2991c9f3-3070-43a9-ada5-52e1f66c5412', 'en', 'Kulturprojekt', 'Cultural project', '2026-09-03 21:22:47.154334+00'),
	('26a9e900-14cb-47b2-addd-e2a4a6a46ee5', 'en', 'Partnerskapet (organisationer och länder)', 'The partnership (organisations and countries)', '2026-09-03 21:22:47.154334+00'),
	('fec9f691-921d-49fb-a8f1-a27bda5a0684', 'en', 'Kunddialoger, piloter, avsiktsförklaringar, betalande användare — det ni faktiskt har.', 'Customer conversations, pilots, letters of intent, paying users — what you actually have.', '2026-09-03 21:22:47.154334+00'),
	('714a432e-0cad-482e-aeed-79ab5ffbe420', 'en', 'Kunskapen tas tillvara i Sverige', 'The knowledge is put to use in Sweden', '2026-09-03 21:22:47.154334+00'),
	('83f78464-e5e5-494f-8ec2-5ed16e0e9304', 'en', 'Kvalitetsmärkningen söks separat och måste finnas innan volontärprojekt kan beviljas.', 'The Quality Label is applied for separately and must be in place before a volunteering project can be approved.', '2026-09-03 21:22:47.154334+00'),
	('6db850bc-4445-40f3-9c8d-95686830c37e', 'en', 'Laddpunkterna', 'The charging points', '2026-09-03 21:22:47.154334+00'),
	('ad2e8ef1-c94b-418c-b879-057039034369', 'en', 'Lagstadgat bidrag till glasögon eller linser för barn och unga; belopp och rutiner varierar per region — kontrollera din regions nivå.', 'A statutory grant towards glasses or contact lenses for children and young people; amounts and routines vary by region — check your region''s level.', '2026-09-03 21:22:47.154334+00'),
	('fbed1c5f-850e-4dc9-97b2-444e642110c6', 'en', 'Land du planerar att återvandra till', 'Country you plan to return to', '2026-09-03 21:22:47.154334+00'),
	('f7b49476-1f4d-471a-8a13-9ffed14a8020', 'en', 'Land där jobbet finns', 'Country where the job is', '2026-09-03 21:22:47.154334+00'),
	('55154081-657c-4b25-9a31-4859014c3d43', 'en', 'Leaderstöd betalas ut i efterhand mot redovisade kostnader.', 'Leader support is paid in arrears against reported costs.', '2026-09-03 21:22:47.154334+00'),
	('7bbffbad-8579-470c-9c3e-4de109d3f8c6', 'en', 'Ligger projektet i en bygd som berörs av vattenkraft eller vindkraft?', 'Is the project located in an area affected by hydropower or wind power?', '2026-09-03 21:22:47.154334+00'),
	('60b21b69-1846-4d17-b372-d80664fb6b76', 'en', 'Ligger projektet inom miljö, areella näringar eller samhällsbyggande?', 'Is the project within the environment, agricultural sciences or spatial planning?', '2026-09-03 21:22:47.154334+00'),
	('4dd07052-01c6-41a5-9479-ac56d20ebf86', 'en', 'Ligger verksamhetsorten i stödområde A eller B (stora delar av Norrland och inre Svealand)?', 'Is your place of business in support area A or B (large parts of Norrland and inner Svealand)?', '2026-09-03 21:22:47.154334+00'),
	('dbb7fbb3-9758-4752-9765-18b174eaa592', 'en', 'Litteraturstödet söks efter utgivning och bedöms på kvalitet — beskriv verket sakligt, inte säljande.', 'Litteraturstödet is applied for after publication and is judged on quality — describe the work factually, not as a sales pitch.', '2026-09-03 21:22:47.154334+00'),
	('6f1ab95d-6bc4-4e9f-8f54-9084efc1e93d', 'en', 'LOK-stödet räknas per genomförd gruppaktivitet och deltagare — närvaroregistrering i IdrottOnline är underlaget.', 'LOK-stödet is counted per completed group activity and participant — attendance registered in IdrottOnline is the evidence.', '2026-09-03 21:22:47.154334+00'),
	('d00204aa-3bb3-432a-bea2-ef89b5d7fa64', 'en', 'Lokalen och åtgärden', 'The premises and the works', '2026-09-03 21:22:47.154334+00'),
	('c62f7fa6-660d-44b6-b11e-82c4275d067a', 'en', 'Lokalen ska ligga i Sverige', 'The premises must be located in Sweden', '2026-09-03 21:22:47.154334+00'),
	('36d0d7a4-2ddc-4342-afc1-89324da2563b', 'en', 'Lokalen ska vara öppen och tillgänglig för allmänheten', 'The premises must be open and accessible to the public', '2026-09-03 21:22:47.154334+00'),
	('44b79948-dbfa-4489-b674-5bbb7b34e2c5', 'en', 'LONA söks via kommunen — föreningar deltar som initiativtagare.', 'LONA is applied for through the municipality — associations take part as initiators.', '2026-09-03 21:22:47.154334+00'),
	('27258e5e-5a42-4d6b-9d8b-b84bdbd4a781', 'en', 'LONA täcker högst halva kostnaden.', 'LONA covers at most half the cost.', '2026-09-03 21:22:47.154334+00'),
	('5ac84386-b10e-4f01-bb1e-ee4786c7bfd0', 'en', 'Låg hushållsinkomst stärker ansökan', 'A low household income strengthens the application', '2026-09-03 21:22:47.154334+00'),
	('00752abe-4ec0-4508-80a9-35d72f83ef4d', 'en', 'Lånedelen är frivillig och kan väljas per vecka — det går att ångra sig senare.', 'The loan part is optional and can be chosen week by week — you can change your mind later.', '2026-09-03 21:22:47.154334+00'),
	('b315b590-5b3c-497e-9274-6b523b7a050a', 'en', 'Läkarutlåtande om arbetsförmåga', 'A doctor''s statement on your capacity to work', '2026-09-03 21:22:47.154334+00'),
	('24281f40-2776-4c02-9e12-e130a97cf3bd', 'en', 'Läkarutlåtandet är det centrala underlaget — ansökan utan det leder nästan alltid till komplettering.', 'The doctor''s statement is the central document — an application without it almost always leads to a request for supplements.', '2026-09-03 21:22:47.154334+00'),
	('e6ab950c-b564-4212-99d4-75c03758aaab', 'en', 'Lösningen', 'The solution', '2026-09-03 21:22:47.154334+00'),
	('b37fea0a-a8fa-4bf0-89fb-4b2f4a8b0fc0', 'en', 'Lösningen ska vara nyskapande jämfört med befintliga alternativ', 'The solution must be innovative compared with existing alternatives', '2026-09-03 21:22:47.154334+00'),
	('bb7ba7af-9071-44ab-8015-86dd27441f82', 'en', 'Marknad och team', 'Market and team', '2026-09-03 21:22:47.154334+00'),
	('190fa933-2998-4849-9fcc-6620795c53b5', 'en', 'Med barn hemma kan etableringstillägg bli aktuellt hos Försäkringskassan.', 'With children at home, etableringstillägg may become relevant at Försäkringskassan.', '2026-09-03 21:22:47.154334+00'),
	('55368160-4689-470d-a4df-685fae9ccd8a', 'en', 'Med egna ord: vad klarar du inte i dag som ett arbete kräver? Försäkringskassan gör alltid den medicinska prövningen — din beskrivning ska stämma med läkarintyget, inte ersätta det.', 'In your own words: what can you not manage today that a job requires? Försäkringskassan always makes the medical assessment — your description should match the medical certificate, not replace it.', '2026-09-03 21:22:47.154334+00'),
	('feae2a8a-770a-48f3-b59e-3e6b1958164e', 'en', 'Medelsförvaltande lärosäte', 'Administering higher-education institution', '2026-09-03 21:22:47.154334+00'),
	('0666820c-3b9d-4a6f-9b02-766826e5b990', 'en', 'Medelsförvaltare (lärosäte)', 'Funds administrator (higher-education institution)', '2026-09-03 21:22:47.154334+00'),
	('1e1df937-5cb2-44fa-b21c-8269b32d0603', 'en', 'Medelsförvaltaren ska vara svensk', 'The funds administrator must be Swedish', '2026-09-03 21:22:47.154334+00'),
	('84e825e8-d173-4c68-9c0d-b43e5275ffc1', 'en', 'Medlemmar och struktur', 'Members and structure', '2026-09-03 21:22:47.154334+00');
INSERT INTO public.kb_translations VALUES
	('8fa12418-442f-4b5f-ba2d-2b2591d795a2', 'en', 'Medlen förvaltas av ett svenskt lärosäte', 'The funds are administered by a Swedish higher-education institution', '2026-09-03 21:22:47.154334+00'),
	('0ef19b0d-feb8-48a0-9161-0af491aed754', 'en', 'Medlen förvaltas av ett svenskt lärosäte eller godkänd medelsförvaltare', 'The funds are administered by a Swedish higher-education institution or an approved funds administrator', '2026-09-03 21:22:47.154334+00'),
	('81e38825-1200-4f3c-a3e8-dabde60a4c37', 'en', 'Medlen förvaltas av lärosäte eller forskningsinstitut', 'The funds are administered by a higher-education institution or a research institute', '2026-09-03 21:22:47.154334+00'),
	('1ba22d78-01c3-453e-8c94-85b7ad06400f', 'en', 'Medlen ska användas till litteraturinköp för folk- eller skolbibliotek', 'The funds must be used to purchase literature for public or school libraries', '2026-09-03 21:22:47.154334+00'),
	('92aba8b2-829b-47e8-a4b1-cf4aa242298d', 'en', 'Medverkande musiker/aktörer', 'Participating musicians / performers', '2026-09-03 21:22:47.154334+00'),
	('f4982373-31a7-46c6-8911-2137928e4074', 'en', 'Merkostnaderna', 'The extra costs', '2026-09-03 21:22:47.154334+00'),
	('0a25086c-da12-4299-bdba-f6e67cb3c478', 'en', 'Merkostnadslån kan täcka undervisningsavgifter — lämna tomt om avgift saknas.', 'A supplementary loan can cover tuition fees — leave blank if there is no fee.', '2026-09-03 21:22:47.154334+00'),
	('398ae5fc-02d7-4b02-b7f8-da799983b078', 'en', 'Minskar projektet industrins processutsläpp eller skapar negativa utsläpp?', 'Does the project reduce industrial process emissions or create negative emissions?', '2026-09-03 21:22:47.154334+00'),
	('ad519bc8-6d38-474c-a979-eb6f8c2c7b40', 'en', 'Minst 60 % av medlemmarna ska vara 6–25 år', 'At least 60 % of the members must be aged 6–25', '2026-09-03 21:22:47.154334+00'),
	('acd477ed-2278-4bce-ab3f-431cfb4b9dba', 'en', 'Minst en partner i ett annat programland', 'At least one partner in another programme country', '2026-09-03 21:22:47.154334+00'),
	('802fcef3-af2c-4510-aaf9-8388fb2a35cd', 'en', 'Minst en partner i ett annat programland krävs.', 'At least one partner in another programme country is required.', '2026-09-03 21:22:47.154334+00'),
	('05f33eb0-7dbc-4bd3-8571-2bb169bf0c0b', 'en', 'Minst en partnergrupp i ett annat programland krävs', 'At least one partner group in another programme country is required', '2026-09-03 21:22:47.154334+00'),
	('459abf4b-ce27-46af-b9aa-c27679bc01b1', 'en', 'Söks av förlag', 'Applied for by publishers', '2026-09-03 21:22:47.16199+00'),
	('159def9d-a8d1-4610-b15e-cf08455a9a40', 'en', 'Minst tre organisationer från tre olika länder krävs — ange samtliga med land.', 'At least three organisations from three different countries are required — list them all with their country.', '2026-09-03 21:22:47.154334+00'),
	('e869fee7-5cef-45aa-989b-3706f3de1a9d', 'en', 'Minst tre partner från tre olika programländer krävs', 'At least three partners from three different programme countries are required', '2026-09-03 21:22:47.154334+00'),
	('e56e3c4f-3f45-4e82-ae28-ed2389c57038', 'en', 'Mobiliteten ska ske till ett annat programland', 'The mobility must take place to another programme country', '2026-09-03 21:22:47.154334+00'),
	('5d39480c-5421-4a24-938c-3c5d348b16a4', 'en', 'Mobiliteterna', 'The mobilities', '2026-09-03 21:22:47.154334+00'),
	('c2918a88-95cb-4f57-999f-268dad83dce7', 'en', 'Mobilitetsplan', 'Mobility plan', '2026-09-03 21:22:47.154334+00'),
	('9f614021-efeb-428b-99a5-99936c644fe8', 'en', 'Musikprojekt', 'Music project', '2026-09-03 21:22:47.154334+00'),
	('5ac4181e-4553-441e-90a1-29a56916d4b4', 'en', 'Målgrupp och delaktighet', 'Target group and participation', '2026-09-03 21:22:47.154334+00'),
	('fbaff751-6fd3-43d8-aa1f-119e4504758f', 'en', 'Målgruppen ska vara barn, unga, äldre eller personer med funktionsnedsättning', 'The target group must be children, young people, older people or people with disabilities', '2026-09-03 21:22:47.154334+00'),
	('518df75e-d795-4b06-b6f0-0499d77998da', 'en', 'Målgruppen ska vara delaktig i projektet', 'The target group must take part in the project', '2026-09-03 21:22:47.154334+00'),
	('d0b82e42-802e-4810-b5b1-d666a3ba5a99', 'en', 'Månatligt bidrag för barn som bor i Sverige, från födseln till 16 års ålder.', 'A monthly allowance for children living in Sweden, from birth until age 16.', '2026-09-03 21:22:47.154334+00'),
	('85e56547-6395-467b-bf94-3f2fe6df4f20', 'en', 'Mätbar miljönytta', 'Measurable environmental benefit', '2026-09-03 21:22:47.154334+00'),
	('9fc329d4-6a49-4d71-92fd-7a29ab2c4369', 'en', 'Namn', 'Name', '2026-09-03 21:22:47.154334+00'),
	('d04bdfc7-eabd-4e4b-8d76-93131dd53db7', 'en', 'Namn (elev eller vårdnadshavare)', 'Name (pupil or guardian)', '2026-09-03 21:22:47.154334+00'),
	('af9e98f5-be02-4ae4-b123-e2afc98a6069', 'en', 'Namn (vårdnadshavare)', 'Name (guardian)', '2026-09-03 21:22:47.154334+00'),
	('ed5f88ce-577d-4ed2-9534-aa16e1d9c8d8', 'en', 'Nationell spridning krävs — normalt verksamhet i minst fem län.', 'National reach is required — normally activity in at least five counties.', '2026-09-03 21:22:47.154334+00'),
	('27a9074d-d2bd-407c-95f5-22ad82559c1b', 'en', 'Naturbruksutbildning, kurser eller praktisk erfarenhet — kravet kan uppfyllas på flera sätt.', 'Agricultural education, courses or practical experience — the requirement can be met in several ways.', '2026-09-03 21:22:47.154334+00'),
	('f64eb5b0-f413-4adf-af35-2c9509bd73fc', 'en', 'Naturvårdsprojektet', 'The nature-conservation project', '2026-09-03 21:22:47.154334+00'),
	('be1a3974-1184-46bb-95ae-0557ae0381ad', 'en', 'Naturvårdsverket erbjuder bidrag till organisationer, företag, föreningar, offentlig sektor och privatpersoner inom miljöområdet.', 'Naturvårdsverket offers grants to organisations, companies, associations, the public sector and private individuals in the environmental field.', '2026-09-03 21:22:47.154334+00'),
	('712bfdc0-a8e5-4148-a47f-bbe384c80c2b', 'en', 'Nordisk dimension', 'Nordic dimension', '2026-09-03 21:22:47.154334+00'),
	('7ccc8102-af19-4131-b633-249d52b63f74', 'en', 'Nykomlingar i Erasmus+ prioriteras', 'Newcomers to Erasmus+ are prioritised', '2026-09-03 21:22:47.154334+00'),
	('9532a8b4-afb6-4669-ba32-e01324806e10', 'en', 'Något konkret som gör skillnad för barnet: en fritidsaktivitet, kläder, utrustning, en cykel. Majblomman ger till barnet, inte till hushållets löpande utgifter.', 'Something concrete that makes a difference for the child: a leisure activity, clothes, equipment, a bicycle. Majblomman gives to the child, not to the household''s running costs.', '2026-09-03 21:22:47.154334+00'),
	('c4825130-6716-4103-9938-fbd7dd8fbc41', 'en', 'Närvaroregistrerad aktivitetsredovisning', 'Activity report with registered attendance', '2026-09-03 21:22:47.154334+00'),
	('7c92013e-8e37-4a83-a5f7-35f4b8979c12', 'en', 'Offert från entreprenör räcker — kommunen kan begära fler.', 'A quotation from a contractor is enough — the municipality may ask for more.', '2026-09-03 21:22:47.154334+00'),
	('e5aec540-3e91-4c6c-a6c2-66cfdf9ad4e0', 'en', 'Offerter styrker kalkylen — stödandelen räknas på faktiska kostnader.', 'Quotations back up the calculation — the support share is based on actual costs.', '2026-09-03 21:22:47.154334+00'),
	('07a49f38-50b5-44e0-9e9a-375c183e0f5e', 'en', 'OID (Organisation ID)', 'OID (Organisation ID)', '2026-09-03 21:22:47.154334+00'),
