	('6894c5d4-a598-4dd3-943b-692ab32b69eb', 'en', 'Projektet ska avse kulturarv', 'The project must concern cultural heritage', '2026-09-03 21:22:47.16199+00'),
	('5d9dcb11-00f2-42fa-b200-9594304842e5', 'en', 'Projektet ska avse miljö- eller klimatåtgärder', 'The project must concern environmental or climate measures', '2026-09-03 21:22:47.16199+00'),
	('ce245438-22fd-41e1-8445-9486773d4771', 'en', 'Projektet ska avse naturvård eller friluftsliv', 'The project must concern nature conservation or outdoor recreation', '2026-09-03 21:22:47.16199+00'),
