INSERT INTO public.kb_translations VALUES
	('7b788e18-70c1-46f2-bd6b-33af31414455', 'es', 'Beskriv åtgärden', 'Describe la actuación', '2026-09-03 21:22:47.184972+00'),
	('d92160cd-ab6e-477c-aedd-1abb41f7d66f', 'es', 'Beskriv övrig finansiering', 'Describe la financiación adicional', '2026-09-03 21:22:47.184972+00'),
	('9282fbec-5f73-4e86-83b4-05839ec577f0', 'es', 'Beskrivning av konstnärlig verksamhet och planer', 'Descripción de la actividad artística y los planes', '2026-09-03 21:22:47.184972+00'),
	('589bddb4-686e-4eba-9c1e-33cb7c1b42c9', 'es', 'Beskrivning av lokalen och åtgärderna', 'Descripción del local y de las obras', '2026-09-03 21:22:47.184972+00'),
	('ee3d58fb-0130-4347-b1e5-33ec70453154', 'es', 'Beskrivning av planerad EU-ansökan', 'Descripción de la solicitud europea prevista', '2026-09-03 21:22:47.184972+00'),
	('0bc7a677-4f89-4a85-8036-cf14d9220e9e', 'es', 'Beskrivning av utvecklingsinsatsen', 'Descripción de la iniciativa de desarrollo', '2026-09-03 21:22:47.184972+00'),
	('7537eb71-a978-4ed4-b771-bb658b2b8835', 'es', 'Beskrivning av åtgärden', 'Descripción de la actuación', '2026-09-03 21:22:47.184972+00'),
	('e1bdfdc8-3f51-4ad3-8519-199c706a5ee2', 'es', 'Betalar den andra föräldern inget eller mindre än fullt underhåll?', '¿El otro progenitor no paga nada o paga menos que la pensión alimenticia completa?', '2026-09-03 21:22:47.184972+00'),
	('e45a1ce0-edfa-44db-96fb-e597836050b6', 'es', 'Betalar den andra föräldern inget, för lite eller oregelbundet? Konkret — det avgör vilken väg Försäkringskassan tar.', '¿El otro progenitor no paga nada, paga poco o paga de forma irregular? Sé concreto: eso determina la vía que seguirá Försäkringskassan.', '2026-09-03 21:22:47.184972+00'),
	('961f4ede-5112-447c-a724-32d5234a3018', 'es', 'Betalar du hyra eller andra boendekostnader?', '¿Paga usted alquiler u otros gastos de vivienda?', '2026-09-03 21:22:47.184972+00'),
	('5fd7ce00-bfc8-46fa-9977-297c58293682', 'es', 'Betalas normalt ut automatiskt tillsammans med barnbidraget.', 'Normalmente se abona de forma automática junto con el barnbidraget.', '2026-09-03 21:22:47.184972+00'),
	('3a4e42c1-ad92-4098-8d7a-9ab2aca7a5d8', 'es', 'Betalas normalt ut automatiskt; ansökan i särskilda fall på Mina sidor hos Försäkringskassan.', 'Normalmente se abona de forma automática; en casos especiales se solicita en Mina sidor de Försäkringskassan.', '2026-09-03 21:22:47.184972+00'),
	('67f4665d-2bdd-4f0d-a874-4c1559120613', 'es', 'Bidrag för att anpassa bostaden vid funktionsnedsättning — t.ex. ramper, dörröppnare eller badrumsanpassning.', 'Subvención para adaptar la vivienda en caso de discapacidad — p. ej. rampas, abridores de puertas o adaptación del baño.', '2026-09-03 21:22:47.184972+00'),
	('8c61e618-ef0c-47b6-a568-3260f236fbd3', 'es', 'Bidrag för att bygga, köpa eller rusta upp allmänna samlingslokaler.', 'Subvenciones para construir, comprar o renovar locales públicos de reunión.', '2026-09-03 21:22:47.184972+00'),
	('f4267283-b5fb-4cef-808f-cc28c61cbb2a', 'es', 'Bidrag för att köpa eller anpassa en bil när en varaktig funktionsnedsättning gör det mycket svårt att förflytta sig eller resa kollektivt.', 'Subvención para comprar o adaptar un coche cuando una discapacidad permanente hace muy difícil desplazarse o usar el transporte público.', '2026-09-03 21:22:47.184972+00'),
	('1304afd4-9ffe-490d-aac3-26779d4939e5', 'es', 'Bidrag för internationella resor och utbyten för yrkesverksamma inom kulturområdet.', 'Subvenciones para viajes e intercambios internacionales de profesionales del sector cultural.', '2026-09-03 21:22:47.184972+00'),
	('2464d220-cfd1-4b7d-8365-a66ca1143113', 'es', 'Bidrag för yrkesverksamma konstnärers internationella utbyten, resor och arbetsvistelser.', 'Subvenciones para intercambios internacionales, viajes y estancias de trabajo de artistas profesionales.', '2026-09-03 21:22:47.184972+00'),
	('bc4b401d-02a7-4ee3-ac85-80101fdcf049', 'es', 'Bidrag ges till avgränsade projekt, inte löpande verksamhet', 'Las ayudas se conceden a proyectos delimitados, no a la actividad corriente', '2026-09-03 21:22:47.184972+00'),
	('89c7512d-bd10-4036-ad81-9ea97bab2e99', 'es', 'Bidrag och frivilligt lån för dig som studerar på gymnasial eller eftergymnasial nivå.', 'Beca y préstamo voluntario para estudios de nivel secundario superior o postsecundario.', '2026-09-03 21:22:47.184972+00'),
	('abb2a807-5583-45f7-b531-6a2e2e8ea4f6', 'es', 'Bidrag och lån', 'Ayuda y préstamo', '2026-09-03 21:22:47.184972+00'),
	('55eb437a-29bf-4106-803c-e99f6c754a5f', 'es', 'Bidrag och lån för studier utomlands, med extra merkostnadslån för t.ex. terminsavgifter och resor.', 'Becas y préstamos para estudiar en el extranjero, con préstamos adicionales para p. ej. tasas académicas y viajes.', '2026-09-03 21:22:47.184972+00'),
	('b2f156ec-0177-48ef-b808-00538debf3bf', 'es', 'Bidrag som hjälper svenska aktörer att förbereda ansökningar till EU-program som Horisont Europa.', 'Subvención que ayuda a actores suecos a preparar solicitudes para programas de la UE como Horisont Europa.', '2026-09-03 21:22:47.184972+00'),
	('e356624c-bba8-4418-996e-35b893e334b8', 'es', 'Bidrag till arbetsgivare som anställer personer med nedsatt arbetsförmåga.', 'Subvención para empleadores que contratan a personas con capacidad de trabajo reducida.', '2026-09-03 21:22:47.184972+00'),
	('6b3f7d3b-d7e4-4d6b-b9a6-91b26c893d5c', 'es', 'Eleven och skolvägen', 'El alumno y el camino a la escuela', '2026-09-03 21:22:47.184972+00'),
	('806c1292-9a8a-46a9-a02c-16d87cfae415', 'es', 'Elevens namn', 'Nombre del alumno', '2026-09-03 21:22:47.184972+00'),
	('87fc226a-bd33-4f5b-bc22-96b3005aad43', 'es', 'Bidrag till boende och hemresor när en gymnasieelev måste bo på studieorten på grund av lång resväg.', 'Subvención para alojamiento y viajes a casa cuando un estudiante de secundaria superior debe vivir en la localidad de estudios por la distancia.', '2026-09-03 21:22:47.184972+00'),
	('618ee726-cca4-44d0-8317-aa56b56398ab', 'es', 'Bidrag till ideella organisationers arbete med att bevara, använda och utveckla kulturarvet.', 'Subvenciones para el trabajo de organizaciones sin ánimo de lucro por conservar, usar y desarrollar el patrimonio cultural.', '2026-09-03 21:22:47.184972+00'),
	('e34c144f-1661-4b72-833e-2d7c48b48aa8', 'es', 'Bidrag till kommunala och lokala naturvårdsprojekt, inklusive våtmarker och friluftsliv.', 'Subvenciones para proyectos municipales y locales de conservación de la naturaleza, incluidos humedales y actividades al aire libre.', '2026-09-03 21:22:47.184972+00'),
	('fcb1b416-03da-4991-acf1-71d24fbd4fad', 'es', 'Bidrag till kommuner för inköp av litteratur till folk- och skolbibliotek.', 'Subvenciones a municipios para la compra de literatura para bibliotecas públicas y escolares.', '2026-09-03 21:22:47.184972+00'),
	('129f39a2-6717-4ad4-8306-df1ffc6caf40', 'es', 'Bidrag till skolhuvudmän för elevers möte med professionell kultur i grundskolan.', 'Subvenciones a titulares de escuelas para el encuentro de los alumnos con la cultura profesional en la escuela obligatoria.', '2026-09-03 21:22:47.184972+00'),
	('61ffa617-f21a-4389-9fb1-f62308b93ed7', 'es', 'Bidrag till sådant ditt barn behöver men som ekonomin inte räcker till: fritidsaktiviteter, kläder, skolutflykter, glasögon, lovaktiviteter med mera.', 'Ayuda para lo que su hijo necesita pero la economía familiar no alcanza a cubrir: actividades de ocio, ropa, excursiones escolares, gafas, actividades vacacionales y más.', '2026-09-03 21:22:47.184972+00'),
	('1c80ab6a-1b1f-4274-a20f-bbaf6e29a74c', 'es', 'Bidrag ur bl.a. Världens Barn, Musikhjälpen och Victoriafonden — söks av svenska ideella organisationer med 90-konto.', 'Ayudas de fondos como Världens Barn, Musikhjälpen y Victoriafonden — solicitadas por organizaciones suecas sin ánimo de lucro con 90-konto.', '2026-09-03 21:22:47.184972+00'),
	('d36b85eb-3d03-4a1a-abf0-09c3e25a2aae', 'es', 'Bidrag ur vattenkrafts- och vindkraftsmedel till projekt som utvecklar bygden.', 'Ayudas de los fondos de energía hidroeléctrica y eólica para proyectos que desarrollan la comarca.', '2026-09-03 21:22:47.184972+00'),
	('93f05855-2995-4891-9d50-b2011fc9c2d6', 'es', 'Bidrag utan lånedel för arbetslösa 25–60 år med kort tidigare utbildning som behöver studera på grundskole- eller gymnasienivå.', 'Beca sin componente de préstamo para desempleados de 25 a 60 años con estudios previos cortos que necesitan estudiar a nivel de primaria o secundaria.', '2026-09-03 21:22:47.184972+00'),
	('62623e4a-d0e9-4457-bb9f-db2c0dbf331e', 'es', 'Bidragen söks av ideella föreningar', 'Las ayudas las solicitan asociaciones sin ánimo de lucro', '2026-09-03 21:22:47.184972+00'),
	('7c48ce91-ac7b-4c6e-a43a-c7fb08dfe403', 'es', 'Bidragen söks av ideella organisationer', 'Las ayudas las solicitan organizaciones sin ánimo de lucro', '2026-09-03 21:22:47.184972+00'),
	('ef6374a4-8120-4bc5-8c5d-4c18b25f6b2a', 'es', 'Bidragen söks i regel av ideella organisationer', 'Por regla general, las ayudas las solicitan organizaciones sin ánimo de lucro', '2026-09-03 21:22:47.184972+00'),
	('7173ef35-98e1-4c94-8099-d7b665dc167a', 'es', 'Bidraget beräknas delvis på ytan — siffran står i hyresavtalet.', 'La ayuda se calcula en parte por la superficie: la cifra figura en el contrato de arrendamiento.', '2026-09-03 21:22:47.184972+00'),
	('c22b94be-ea16-4b14-a50b-3e765d7ae30f', 'es', 'Bidraget förvaltas av ett svenskt lärosäte — det ska bekräfta åtagandet.', 'La ayuda la gestiona una institución de educación superior sueca, que debe confirmar el compromiso.', '2026-09-03 21:22:47.184972+00'),
	('ac855243-2913-4114-bb40-83362e03cb21', 'es', 'Bidraget gäller från och med det år du fyller 24', 'La ayuda se aplica a partir del año en que cumples 24', '2026-09-03 21:22:47.184972+00'),
	('c1782f47-0167-4905-a2c6-87e95980269b', 'es', 'Bidraget gäller privatpersoner', 'La ayuda es para particulares', '2026-09-03 21:22:47.184972+00'),
	('9d31ef7c-f934-48d9-837d-647c7eeb21e9', 'es', 'Bidraget ska användas för att förbereda en EU-ansökan', 'La ayuda debe usarse para preparar una solicitud europea', '2026-09-03 21:22:47.184972+00'),
	('74a30526-f0b6-468d-a688-f769c58531eb', 'es', 'Bidraget stäms av mot årsinkomsten i efterhand — en för låg uppskattning kan ge återkrav.', 'La ayuda se ajusta después con los ingresos anuales: una estimación demasiado baja puede dar lugar a una reclamación de devolución.', '2026-09-03 21:22:47.184972+00'),
	('6d717d0d-84ba-4d10-aa2e-2ddf2e919f56', 'es', 'Bidraget söks av enskilda yrkesverksamma konstnärer', 'La ayuda la solicitan artistas profesionales a título individual', '2026-09-03 21:22:47.184972+00'),
	('dd6481e7-d94e-4d5b-baa4-7f18786a9c2b', 'es', 'Bidraget söks av privatpersoner', 'La ayuda la solicitan particulares', '2026-09-03 21:22:47.184972+00'),
	('5fe257bc-32b0-44e8-b6a8-763824a7b09a', 'es', 'Bidraget söks av vårdnadshavare', 'La ayuda la solicita un tutor', '2026-09-03 21:22:47.184972+00'),
	('5a47ed79-73ac-429a-bd9b-60fd8ba191c3', 'es', 'Bidraget söks för barn av vårdnadshavare', 'La ayuda la solicita un tutor en nombre del niño', '2026-09-03 21:22:47.184972+00'),
	('cb9e79d3-a32c-403e-b413-dc47d7ae138b', 'es', 'Bidraget söks för barn av vårdnadshavare eller t.ex. skolsköterska', 'La ayuda la solicita para el niño un tutor o, por ejemplo, la enfermera escolar', '2026-09-03 21:22:47.184972+00'),
	('a3ed95f7-a351-4da7-abe7-9cb6f8699d75', 'es', 'Bidraget är högst halva kostnaden per laddpunkt, med takbelopp.', 'La ayuda cubre como máximo la mitad del coste por punto de recarga, con un importe máximo.', '2026-09-03 21:22:47.184972+00'),
	('61ef751b-0434-4f55-ada8-dedaacab6d2d', 'es', 'Bidragets tak varierar mellan regioner — hela kostnaden ersätts inte alltid.', 'El importe máximo varía según la región: no siempre se cubre todo el coste.', '2026-09-03 21:22:47.184972+00');
INSERT INTO public.kb_translations VALUES
	('6f7e65ed-5c86-4d33-8381-106dd6887d05', 'es', 'Bidrar projektet till energiomställningen?', '¿El proyecto contribuye a la transición energética?', '2026-09-03 21:22:47.184972+00'),
	('5552da67-6936-48f4-a9bb-777ae5df5f46', 'es', 'Bidrar till energiomställningen', 'Contribuye a la transición energética', '2026-09-03 21:22:47.184972+00'),
	('c3fa68fe-0f10-455f-bc75-12d6a249e9c8', 'es', 'Boende, försörjning och nätverk i ursprungslandet. OBS: beslutet är oåterkalleligt i bidragshänseende — uppehållstillståndet återkallas normalt. Ta det lugnt med beslutet och kontrollera aktuella belopp hos Migrationsverket.', 'Vivienda, sustento y red de contactos en el país de origen. ATENCIÓN: en cuanto a esta ayuda la decisión es irreversible; el permiso de residencia suele revocarse. Tómate tu tiempo y consulta los importes vigentes con Migrationsverket.', '2026-09-03 21:22:47.184972+00'),
	('4af54a36-498d-4dde-a954-1a76ffe82fd7', 'es', 'Boendekostnad per månad (kr)', 'Coste de la vivienda al mes (kr)', '2026-09-03 21:22:47.184972+00'),
	('eb45672f-12ed-4a41-bf37-621953d93e7f', 'es', 'Bolaget', 'La empresa', '2026-09-03 21:22:47.184972+00'),
	('4a117526-0aab-4154-adf9-9f79f16d7c2f', 'es', 'Bolaget ska vara registrerat i Sverige', 'La empresa debe estar registrada en Suecia', '2026-09-03 21:22:47.184972+00'),
	('5cfd9d35-377c-47ce-99e3-09662597a708', 'es', 'Bolaget ska vara ungt (typiskt max ca 5 år — se aktuell utlysning)', 'La empresa debe ser joven (normalmente un máximo de unos 5 años; consulta la convocatoria vigente)', '2026-09-03 21:22:47.184972+00'),
	('914eb899-f521-4369-81c2-4240beecff8e', 'es', 'Bolagets namn', 'Nombre de la empresa', '2026-09-03 21:22:47.184972+00'),
	('6470d3c0-b140-4ebf-9448-fba620e1ecca', 'es', 'Bor du ensam i egen bostad?', '¿Vives solo en una vivienda propia?', '2026-09-03 21:22:47.184972+00'),
	('76534ed1-4d73-434c-806a-0fe7776b08ef', 'es', 'Bor du och barnets andra förälder på skilda håll?', '¿Usted y el otro progenitor del menor viven separados?', '2026-09-03 21:22:47.184972+00'),
	('a994455e-7267-4402-a208-a72a4df4babf', 'es', 'Bostaden', 'La vivienda', '2026-09-03 21:22:47.184972+00'),
	('27ca395f-be05-4a4a-8eed-f7e0caf867bd', 'es', 'Bostaden ska behöva anpassas', 'La vivienda debe necesitar una adaptación', '2026-09-03 21:22:47.184972+00'),
	('009cd694-7ca2-40d0-af3d-ad4b46aaa42b', 'es', 'Bostaden ska ligga i Sverige', 'La vivienda debe estar en Suecia', '2026-09-03 21:22:47.184972+00'),
	('4028e179-71fa-4689-9c29-0bcbf9a675be', 'es', 'Bostadens yta (kvm)', 'Superficie de la vivienda (m²)', '2026-09-03 21:22:47.184972+00'),
	('d81ef516-ef1f-43ff-9e11-78fdcf3365c3', 'es', 'Elever som målgrupp', 'El alumnado como grupo destinatario', '2026-09-03 21:22:47.184972+00'),
	('db2845de-61cb-471e-b60a-191e9aa23f4b', 'es', 'Investeringskalkyl med offerter', 'Cálculo de la inversión con presupuestos de proveedores', '2026-09-03 21:22:47.20071+00'),
	('ae0c9a06-afe2-4ec4-a542-c2a7d9860e3d', 'es', 'Bostadsbidraget stäms av mot årsinkomsten i efterhand — en för låg uppskattning kan ge återkrav. Ta i lite uppåt hellre än neråt.', 'El bostadsbidrag se ajusta después con los ingresos anuales: una estimación demasiado baja puede dar lugar a una reclamación de devolución. Mejor estimar un poco al alza que a la baja.', '2026-09-03 21:22:47.184972+00'),
	('be5a7446-aa9e-4988-9581-f14fbc1e47bd', 'es', 'Budget', 'Presupuesto', '2026-09-03 21:22:47.184972+00'),
	('1aea2411-6c1c-4c2a-9ef1-33e0ce96b769', 'es', 'Budget enligt programmets schabloner', 'Presupuesto según los baremos estándar del programa', '2026-09-03 21:22:47.184972+00'),
	('02c8f4a6-d7ad-4ec5-8b00-1b1f996dacf2', 'es', 'Budget och finansiering', 'Presupuesto y financiación', '2026-09-03 21:22:47.184972+00'),
	('59fd73d7-bae7-4029-be22-0ee8d7036866', 'es', 'Budget och överlevnad', 'Presupuesto y continuidad', '2026-09-03 21:22:47.184972+00'),
	('b7ffe73f-6e8d-4f9e-94a8-29a973492929', 'es', 'Byggnader, maskiner eller inventarier — och hur investeringen ökar sysselsättningen eller konkurrenskraften på orten.', 'Edificios, maquinaria o equipamiento, y cómo la inversión aumenta el empleo o la competitividad en la localidad.', '2026-09-03 21:22:47.184972+00'),
	('eb059c4c-df81-46f7-bb02-78b750d88c2b', 'es', 'Checkar till små företag för att ta in extern kompetens vid internationalisering eller digitalisering.', 'Cheques para pequeñas empresas para incorporar competencias externas en internacionalización o digitalización.', '2026-09-03 21:22:47.184972+00'),
	('b9ee4438-09e8-4c41-af07-a16ad87980a2', 'es', 'Checkarna riktar sig typiskt till företag med 2–49 anställda — regionens villkor styr.', 'Los cheques suelen dirigirse a empresas de 2 a 49 empleados; mandan las condiciones de la región.', '2026-09-03 21:22:47.184972+00'),
	('730764c2-23ec-485e-aeed-4c23bbd0dd35', 'es', 'Checken ska användas för utvecklingsinsats med extern kompetens', 'El cheque debe usarse para una actuación de desarrollo con competencia externa', '2026-09-03 21:22:47.184972+00'),
	('f29d82df-d181-4361-86d2-1004fd50beeb', 'es', 'Checken täcker normalt högst hälften av kostnaden — resten är egen insats.', 'El cheque cubre normalmente como máximo la mitad del coste; el resto es aportación propia.', '2026-09-03 21:22:47.184972+00'),
	('bbb57d41-cc90-48c8-aab3-59f6063039f8', 'es', 'CV eller konstnärlig meritförteckning', 'CV o currículum artístico', '2026-09-03 21:22:47.184972+00'),
	('eadb896d-def2-40eb-8802-021c3b7ece43', 'es', 'CV för nyckelfunktioner', 'CV de las funciones clave', '2026-09-03 21:22:47.184972+00'),
	('78c6c58b-ddd4-41d1-b5ff-8cdd35618ebd', 'es', 'CV för nyckelpersoner', 'CV de las personas clave', '2026-09-03 21:22:47.184972+00'),
	('e88a7b70-2f13-47ba-9940-825e004c18fa', 'es', 'CV och publikationslista', 'CV y lista de publicaciones', '2026-09-03 21:22:47.184972+00'),
	('644df033-0db7-4469-b0e8-d3073610d774', 'es', 'Datum för start eller övertagande', 'Fecha de inicio o de traspaso', '2026-09-03 21:22:47.184972+00'),
	('4afc26e3-c43c-46f5-8f83-1a340498cab8', 'es', 'De flesta mindre företagsstöd är de minimis-stöd. Taket är 300 000 euro per treårsperiod — nytt stöd över taket är otillåtet, och uppgiften intygas på heder och samvete hos finansiären.', 'La mayoría de las ayudas menores a empresas son ayudas de minimis. El límite es de 300 000 euros por trienio: no se permite nueva ayuda por encima del límite, y el dato se declara bajo palabra de honor ante el financiador.', '2026-09-03 21:22:47.184972+00'),
	('d91d266b-2fd8-43b0-ad4b-7c85e440474c', 'es', 'Delaktigheten är ett skarpt krav — beskriv mekanismen, inte avsikten: vem ur målgruppen gör vad?', 'La participación es un requisito estricto: describe el mecanismo, no la intención. ¿Quién del grupo destinatario hace qué?', '2026-09-03 21:22:47.184972+00'),
	('a57b3fee-bd39-4e61-b4e6-020ec86db606', 'es', 'Deltagare och partner', 'Participantes y socios', '2026-09-03 21:22:47.184972+00'),
	('0f207f82-5dfb-47c8-ae8e-9be1179d4e53', 'es', 'Deltagarna ska vara 13–30 år', 'Los participantes deben tener entre 13 y 30 años', '2026-09-03 21:22:47.184972+00'),
	('ccb0d640-dd4d-4397-8ac7-2f143fa3af0d', 'es', 'Deltar du i ett program hos Arbetsförmedlingen (t.ex. jobb- och utvecklingsgarantin)?', '¿Participa usted en un programa de Arbetsförmedlingen (p. ej. jobb- och utvecklingsgarantin)?', '2026-09-03 21:22:47.184972+00'),
	('87430010-06e5-4103-8a84-e75af2a42207', 'es', 'Demokratisk uppbyggnad krävs', 'Se exige una estructura democrática', '2026-09-03 21:22:47.184972+00'),
	('2b13d792-da65-42b6-b1cd-5c59acb60eff', 'es', 'Demokratiskt uppbyggd organisation', 'Organización de estructura democrática', '2026-09-03 21:22:47.184972+00'),
	('713b434a-0806-4324-8c73-1e350facd987', 'es', 'Den andra föräldern betalar inte underhåll (eller för lite)', 'El otro progenitor no paga la pensión alimenticia (o paga demasiado poco)', '2026-09-03 21:22:47.184972+00'),
	('b1328672-9d77-45b1-87dd-1781e2274f06', 'es', 'Den anställda ska ha nedsatt arbetsförmåga på grund av funktionsnedsättning eller ohälsa', 'La persona empleada debe tener la capacidad laboral reducida por discapacidad o mala salud', '2026-09-03 21:22:47.184972+00'),
	('33069d71-a0e8-4408-9654-e6242539639e', 'es', 'Den som anställs ska ha varit borta från arbetslivet en längre tid eller vara nyanländ', 'La persona contratada debe haber estado alejada del mercado laboral mucho tiempo o ser recién llegada', '2026-09-03 21:22:47.184972+00'),
	('47989956-80b8-4250-883d-6a5fc9567eb0', 'es', 'Den som bor ensam kan ha rätt till bostadsersättning.', 'Quien vive solo puede tener derecho a bostadsersättning (complemento de vivienda).', '2026-09-03 21:22:47.184972+00'),
	('b039a48e-8f88-4ca7-ad10-9f5c74571561', 'es', 'Det här är prövningens kärna: koppla utbildningen till faktisk efterfrågan — en bransch som rekryterar, en roll din arbetsgivare behöver. Söktrycket är högt och generiska motiveringar sållas bort.', 'Este es el núcleo de la evaluación: vincula la formación con una demanda real, un sector que contrata, un puesto que necesita tu empleador. Hay mucha competencia y las motivaciones genéricas se descartan.', '2026-09-03 21:22:47.184972+00'),
	('c7900adb-3944-43b6-80e4-d78a334c9215', 'es', 'Det ska finnas en sparbank/sparbanksstiftelse i ert verksamhetsområde', 'Debe haber una caja de ahorros o una fundación de caja de ahorros en vuestro ámbito de actuación', '2026-09-03 21:22:47.184972+00'),
	('9d57a7fa-1eba-4fc2-9fb5-9c323f3150cc', 'es', 'Det ska vara mycket svårt att förflytta sig på egen hand eller använda allmänna kommunikationer', 'Debe ser muy difícil desplazarse por cuenta propia o usar el transporte público', '2026-09-03 21:22:47.184972+00'),
	('47da3ba6-fd4e-420b-b4b3-692024b88ed2', 'es', 'Detaljerad budget', 'Presupuesto detallado', '2026-09-03 21:22:47.184972+00'),
	('b554bb8e-168e-4592-9c65-28696dc55529', 'es', 'Detaljerad projektbudget', 'Presupuesto detallado del proyecto', '2026-09-03 21:22:47.184972+00'),
	('1fb78453-8d68-40b4-bdc5-3d0a7db61957', 'es', 'Diagnos eller svårigheter i vardagen — läkarutlåtandet bär den medicinska bedömningen, din beskrivning bär vardagen.', 'Diagnóstico o dificultades cotidianas: el informe médico aporta la valoración clínica y tu descripción aporta la vida diaria.', '2026-09-03 21:22:47.184972+00'),
	('2d9c2670-a909-454e-9fd9-43f445f2dd46', 'es', 'Din beräknade inkomst i år, före skatt (kr)', 'Tus ingresos estimados de este año, antes de impuestos (kr)', '2026-09-03 21:22:47.184972+00'),
	('b6a92b15-3c69-47db-99f5-c879b42f71d6', 'es', 'Din inkomst ska vara låg', 'Tus ingresos deben ser bajos', '2026-09-03 21:22:47.184972+00');
INSERT INTO public.kb_translations VALUES
	('9158f3a6-026c-4a84-afab-8c187cc23f29', 'es', 'Din konstnärliga verksamhet', 'Tu actividad artística', '2026-09-03 21:22:47.184972+00'),
	('a1632613-ca6f-48a3-b898-4acf96b3720e', 'es', 'Din relation till den som är sjuk', 'Tu relación con la persona enferma', '2026-09-03 21:22:47.184972+00'),
	('0360fdd4-054f-46cc-8a67-b9f2b3618b1d', 'es', 'Din senast avslutade utbildning', 'Tus últimos estudios finalizados', '2026-09-03 21:22:47.184972+00'),
	('cca974b5-5f85-4618-81af-690a95e4eeae', 'es', 'Din situation', 'Tu situación', '2026-09-03 21:22:47.184972+00'),
	('72a2c04b-ebb1-47cb-bb78-4f4bfcd0191c', 'es', 'Din utbildning och erfarenhet inom området', 'Tu formación y experiencia en el ámbito', '2026-09-03 21:22:47.184972+00'),
	('c0c81aee-42f3-47a1-b255-0f7c1716c237', 'es', 'Ditt arbetsliv', 'Tu vida laboral', '2026-09-03 21:22:47.184972+00'),
	('51ddb52e-977f-412a-99c2-ee360868a140', 'es', 'Du (eller ditt barn) ska ha en varaktig funktionsnedsättning', 'Tú (o tu hijo) debéis tener una discapacidad permanente', '2026-09-03 21:22:47.184972+00'),
	('e55f0cea-94fc-4d7e-86ca-c8b3fc17891e', 'es', 'Du eller någon i hushållet ska ha en bestående funktionsnedsättning', 'Tú o alguien del hogar debéis tener una discapacidad permanente', '2026-09-03 21:22:47.184972+00'),
	('ede21185-54d5-45ba-960c-b552b823b5d3', 'es', 'Föreningen ska vara ansluten till ett specialidrottsförbund inom RF', 'La asociación debe estar afiliada a una federación deportiva nacional dentro de RF', '2026-09-03 21:22:47.192774+00'),
	('9c88d0b1-808c-4ce0-b4a8-da1cd445ccbb', 'es', 'Du ska avstå från förvärvsarbete för att vårda eller vara nära en närstående vars sjukdom är ett påtagligt hot mot livet', 'Debes dejar el trabajo remunerado para cuidar o acompañar a un allegado cuya enfermedad supone una amenaza grave para su vida', '2026-09-03 21:22:47.184972+00'),
	('9da87c6a-9aff-4804-93d5-a62646f4cc9c', 'es', 'Du ska betala för ditt boende', 'Debes pagar por tu vivienda', '2026-09-03 21:22:47.184972+00'),
	('df23483d-a728-4808-9246-760c35142923', 'es', 'Du ska bo i Sverige', 'Debes vivir en Suecia', '2026-09-03 21:22:47.184972+00'),
	('2af50fc3-9d2c-43ea-8ba5-34d7425b4d5a', 'es', 'Du ska delta i ett arbetsmarknadspolitiskt program', 'Debes participar en un programa de política de empleo', '2026-09-03 21:22:47.184972+00'),
	('350a4a91-68cb-4af8-a30e-7e9d5a13e702', 'es', 'Du ska frivilligt planera att flytta tillbaka till ditt ursprungsland permanent', 'Debes planear de forma voluntaria regresar a tu país de origen de forma permanente', '2026-09-03 21:22:47.184972+00'),
	('17484b20-d0b8-48be-8007-f0e1ed567ac9', 'es', 'Du ska ha (eller vänta) barn som du avstår arbete för att ta hand om', 'Debes tener (o esperar) un hijo por el que dejas de trabajar para cuidarlo', '2026-09-03 21:22:47.184972+00'),
	('d2f825ad-100e-4e39-87a5-fee4f2fab635', 'es', 'Du ska ha arbetat i genomsnitt minst 16 h/vecka i minst 8 år', 'Debes haber trabajado una media de al menos 16 h semanales durante un mínimo de 8 años', '2026-09-03 21:22:47.184972+00'),
	('0319916a-4959-47a3-900a-3a4f757b0907', 'es', 'Du ska ha barn (normalt under 12 år) som du vårdar när det är sjukt', 'Debes tener un hijo (normalmente menor de 12 años) al que cuidas cuando está enfermo', '2026-09-03 21:22:47.184972+00'),
	('f5b18382-5660-4df0-89b2-27fd0d53ed67', 'es', 'Du ska ha barn (upp till 18 år) som bor hos dig', 'Debes tener un hijo (hasta 18 años) que viva contigo', '2026-09-03 21:22:47.184972+00'),
	('9eb8694b-2f25-4849-bd52-53a651453842', 'es', 'Du ska ha barn som bor hos dig', 'Debes tener un hijo que viva contigo', '2026-09-03 21:22:47.184972+00'),
	('f5b9876f-7dea-4ae0-af47-525db4263702', 'es', 'Du ska ha barn som bor hos dig (helt eller växelvis)', 'Debes tener un hijo que viva contigo (a tiempo completo o en custodia alterna)', '2026-09-03 21:22:47.184972+00'),
	('19a5bd9e-28d6-499a-bdbc-1426bf130902', 'es', 'Du ska ha barn under 16 år som bor hos dig', 'Debes tener un hijo menor de 16 años que viva contigo', '2026-09-03 21:22:47.184972+00'),
	('a0d16247-99cc-4920-a49f-2dc4300bc76e', 'es', 'Du ska ha kort tidigare utbildning och behöva studier på grundskole- eller gymnasienivå', 'Debes tener poca formación previa y necesitar estudios de nivel obligatorio o secundario superior', '2026-09-03 21:22:47.184972+00'),
	('9c232adf-bcee-4ac1-b82e-b20741778d8e', 'es', 'Du ska ha uppehållstillstånd som flykting eller skyddsbehövande (eller vara nära anhörig till någon som har det)', 'Debes tener un permiso de residencia como refugiado o persona necesitada de protección (o ser familiar cercano de alguien que lo tenga)', '2026-09-03 21:22:47.184972+00'),
	('33ec1eb1-d34e-4301-8aee-88468255ab2d', 'es', 'Du ska ha uppnått riktåldern för pension (67 år från 2026)', 'Debes haber alcanzado la edad de referencia para la jubilación (67 años desde 2026)', '2026-09-03 21:22:47.184972+00'),
	('c5901e80-3eb0-4588-aa51-85378c41f194', 'es', 'Du ska nyligen ha fått uppehållstillstånd som skyddsbehövande eller anhörig', 'Debes haber obtenido recientemente un permiso de residencia como persona necesitada de protección o como familiar', '2026-09-03 21:22:47.184972+00'),
	('8a93fa2c-0561-4c75-a1eb-37ef1846bda6', 'es', 'Du ska planera att starta företag', 'Debes tener previsto crear una empresa', '2026-09-03 21:22:47.184972+00'),
	('3a5257d2-52e3-4d98-9e03-4b887f725048', 'es', 'Du ska planera studier som stärker din ställning på arbetsmarknaden', 'Debes planear estudios que refuercen tu posición en el mercado laboral', '2026-09-03 21:22:47.184972+00'),
	('09f2b1ff-a472-4006-8af8-d04b42e8dc7e', 'es', 'Du ska sakna sparande eller tillgångar som kan täcka behoven', 'No debes tener ahorros ni bienes que puedan cubrir las necesidades', '2026-09-03 21:22:47.184972+00'),
	('28d5536d-12d6-4812-a3d3-25720dadfabe', 'es', 'Du ska studera eller planera att börja studera', 'Debes estar estudiando o tener previsto empezar a estudiar', '2026-09-03 21:22:47.184972+00'),
	('e5662224-934b-4d10-a69f-e14e107c5efa', 'es', 'Du ska söka eller ha fått jobb i ett annat EU-/EES-land', 'Debes estar buscando o haber conseguido un empleo en otro país de la UE o del EEE', '2026-09-03 21:22:47.184972+00'),
	('5339822f-85da-4278-b445-499ba5abe9e7', 'es', 'Du ska ta ut hel allmän pension', 'Debes percibir la pensión general completa', '2026-09-03 21:22:47.184972+00'),
	('b1a44be7-b52e-4a96-9eba-958e3803ae87', 'es', 'Du ska vara 19–29 år', 'Debes tener entre 19 y 29 años', '2026-09-03 21:22:47.184972+00'),
	('018920c5-1389-4d26-81b0-5c7a2784eb05', 'es', 'Du ska vara arbetslös och anmäld hos Arbetsförmedlingen', 'Debes estar en paro e inscrito en Arbetsförmedlingen', '2026-09-03 21:22:47.184972+00'),
	('6a826be1-ee95-42f6-b83e-6b698ee75258', 'es', 'Du ska vara bosatt i ett EU-land (här: Sverige)', 'Debes residir en un país de la UE (aquí: Suecia)', '2026-09-03 21:22:47.184972+00'),
	('dc4cad60-578f-4b0c-b0bd-c21d96115864', 'es', 'Du ska vara försäkrad i Sverige', 'Debes estar asegurado en Suecia', '2026-09-03 21:22:47.184972+00'),
	('2da7d357-c2dd-48c5-a0c5-62b157974c1f', 'es', 'Du ska vara inskriven hos Arbetsförmedlingen', 'Debes estar inscrito en Arbetsförmedlingen', '2026-09-03 21:22:47.184972+00'),
	('2f6621fd-ca88-4dc8-86a2-2d68cd21960b', 'es', 'Du ska vara inskriven hos Arbetsförmedlingen i Sverige', 'Debes estar inscrito en Arbetsförmedlingen en Suecia', '2026-09-03 21:22:47.184972+00'),
	('3ab177dc-42d3-46f1-9399-c22e1a240a1b', 'es', 'Du ska vara inskriven hos Arbetsförmedlingen och aktivt söka arbete', 'Debes estar inscrito en Arbetsförmedlingen y buscar trabajo activamente', '2026-09-03 21:22:47.184972+00'),
	('34c21d41-7962-4592-af01-f5c35c106e4c', 'es', 'Du ska vara inskriven hos Arbetsförmedlingen och delta i etableringsprogrammet', 'Debes estar inscrito en Arbetsförmedlingen y participar en el programa de establecimiento', '2026-09-03 21:22:47.184972+00'),
	('d980931b-179a-4eb6-a233-93a5089c005c', 'es', 'Du ska vara inskriven som arbetssökande', 'Debes estar inscrito como demandante de empleo', '2026-09-03 21:22:47.184972+00'),
	('01e14a3c-32a3-4cea-adfa-e5e35c815a95', 'es', 'Du ska vara mellan 18 och 28 år', 'Debes tener entre 18 y 28 años', '2026-09-03 21:22:47.184972+00'),
	('5dcfe54e-47bb-4288-af58-cfb1295af66b', 'es', 'Du ska vara mellan 25 och 60 år', 'Debes tener entre 25 y 60 años', '2026-09-03 21:22:47.184972+00'),
	('9f983616-9103-4ef2-8fcb-b03ecbd5b194', 'es', 'Efterhandsstöd till förlag för utgivning av kvalitetslitteratur.', 'Apoyo a posteriori a editoriales por la publicación de literatura de calidad.', '2026-09-03 21:22:47.184972+00'),
	('fc0f639c-8491-448b-86c7-0f6a6655c34d', 'es', 'Egna medel, andra bidrag, intäkter. Lämna tomt om allt söks här.', 'Fondos propios, otras ayudas, ingresos. Déjalo en blanco si todo se solicita aquí.', '2026-09-03 21:22:47.184972+00'),
	('7372cef8-9c52-4667-b8c7-c39bac3bb174', 'es', 'Ekonomi', 'Economía', '2026-09-03 21:22:47.184972+00'),
