INSERT INTO public.kb_translations VALUES
	('51e3164c-e614-4a2a-a3aa-e2a193c2c10b', 'es', 'Ekonomiskt stöd under uppstarten för arbetssökande som startar eget företag.', 'Apoyo económico durante la fase inicial para demandantes de empleo que crean su propia empresa.', '2026-09-03 21:22:47.184972+00'),
	('41cb1880-44e8-4e01-8ebd-b37f64449ae7', 'es', 'Eleven behöver bo på studieorten på grund av lång eller besvärlig resväg', 'El alumno necesita vivir en la localidad de estudios por un trayecto largo o complicado', '2026-09-03 21:22:47.184972+00'),
	('47cb84bc-5ac3-40cd-9895-11d12223557f', 'es', 'Eleven går på gymnasiet med studiehjälp', 'El alumno cursa la secundaria superior y recibe studiehjälp', '2026-09-03 21:22:47.184972+00'),
	('d21d3dc3-85eb-46cc-b207-f9a969715856', 'es', 'Elevresestödet förutsätter studiehjälp — den kommer automatiskt för de flesta gymnasieelever under 20.', 'La ayuda para desplazamientos del alumnado exige tener studiehjälp, que la mayoría de los alumnos de secundaria superior menores de 20 años reciben automáticamente.', '2026-09-03 21:22:47.184972+00'),
	('734512f7-5930-40c3-a582-6e336c5e6d05', 'es', 'En energikartläggning eller leverantörsberäkning styrker siffran.', 'Una auditoría energética o un cálculo del proveedor respalda la cifra.', '2026-09-03 21:22:47.184972+00'),
	('f9425ad4-6604-4ddf-aee9-f21c88fe3175', 'es', 'En påbörjad investering diskvalificerar hela ansökan — beställ inget förrän ansökan är inne.', 'Una inversión ya iniciada descalifica toda la solicitud: no encargues nada hasta haberla presentado.', '2026-09-03 21:22:47.192774+00'),
