INSERT INTO public.kb_translations VALUES
	('f289d829-7db3-4115-b3c7-c68e2477a82c', 'es', 'Registreras i EU:s Organisation Registration System med EU Login.', 'Se registra en el Organisation Registration System de la UE con EU Login.', '2026-09-03 21:22:47.207174+00'),
	('9556d3e9-f29c-4d29-9fd1-528cd0b59f82', 'es', 'Repertoar, produktioner, spelplatser och publik — verksamhetsbidraget bedöms på helheten, inte enskilda projekt.', 'Repertorio, producciones, espacios y público: la ayuda a la actividad se valora en conjunto, no por proyectos sueltos.', '2026-09-03 21:22:47.207174+00'),
