	('a48e858f-a231-4393-ba4d-4310a4815091', 'es', 'Sökande ska vara ett förlag med professionell utgivning', 'El solicitante debe ser una editorial con actividad editorial profesional', '2026-09-03 21:22:47.207174+00'),
	('c23bce20-7e45-4b59-a50e-35bc3dbec747', 'es', 'Sökande ska vara förening eller stiftelse', 'El solicitante debe ser una asociación o una fundación', '2026-09-03 21:22:47.207174+00'),
	('e38f2c83-5856-4890-b1d9-735c94766931', 'es', 'Sökande ska vara huvudman för förskoleklass/grundskola', 'El solicitante debe ser el titular de una clase preescolar o de la educación obligatoria', '2026-09-03 21:22:47.207174+00'),
	('8c7138c3-fc1b-4b0a-99ef-33697a193ecc', 'es', 'Sökande ska vara skolhuvudman', 'El solicitante debe ser el titular del centro escolar', '2026-09-03 21:22:47.207174+00'),
	('90b62ae5-1336-41f6-a608-d4ee3e2e891f', 'es', 'Sökande ska vara svensk organisation', 'El solicitante debe ser una organización sueca', '2026-09-03 21:22:47.207174+00'),
	('5e56a29d-05b8-4336-93d9-ab782ae4ceb9', 'es', 'Sökande ska vara verksam i Sverige', 'El solicitante debe estar activo en Suecia', '2026-09-03 21:22:47.207174+00');
