INSERT INTO public.kb_translations VALUES
	('1e2246b3-c32c-42aa-857c-8ed4e896c67f', 'ar', 'Ansökan görs hos din kommun, ofta via e-tjänst eller blankett, med intyg.', 'يُقدَّم الطلب إلى بلديتك، غالبًا عبر خدمة إلكترونية أو استمارة، مع الشهادات المطلوبة.', '2026-09-03 21:22:47.265689+00'),
	('d3119e19-fedd-4ea8-99bf-75deeff4ae42', 'ar', 'Ansökan görs hos Försäkringskassan; läkarutlåtande krävs.', 'يُقدَّم الطلب لدى Försäkringskassan؛ ويلزم تقرير طبي.', '2026-09-03 21:22:47.265689+00'),
	('87d8f5cd-e968-444e-957b-a933524ba53f', 'ar', 'Ansökan görs hos Försäkringskassan; läkarutlåtande om funktionsnedsättningen och körkortsuppgifter behövs.', 'يُقدَّم الطلب لدى Försäkringskassan؛ ويلزم تقرير طبي عن الإعاقة وبيانات رخصة القيادة.', '2026-09-03 21:22:47.265689+00'),
	('83cc2b7f-6136-4b8b-ae85-b6c4e8a54f52', 'ar', 'Ansökan görs hos länsstyrelsen i ditt län, ofta via e-tjänst.', 'يُقدَّم الطلب لدى länsstyrelsen (المجلس الإداري للمقاطعة) في مقاطعتك، غالبًا عبر خدمة إلكترونية.', '2026-09-03 21:22:47.265689+00'),
	('1315af04-3938-444f-960e-5b08218eeea3', 'ar', 'Ansökan görs hos Migrationsverket före utresan.', 'يُقدَّم الطلب لدى Migrationsverket قبل مغادرة البلد.', '2026-09-03 21:22:47.265689+00'),
	('e893df23-8b6f-47d5-98ca-f5c9c42e6981', 'ar', 'Ansökan görs hos Pensionsmyndigheten (kräver e-legitimation).', 'يُقدَّم الطلب لدى Pensionsmyndigheten (يتطلب e-legitimation، الهوية الإلكترونية السويدية).', '2026-09-03 21:22:47.265689+00'),
	('b69ca89f-6346-4f57-95c0-e5dfff04cd69', 'ar', 'Ansökan görs hos socialtjänsten i din kommun — ofta via kommunens e-tjänst eller ett bokat besök.', 'يُقدَّم الطلب إلى الخدمات الاجتماعية في بلديتك — غالبًا عبر الخدمة الإلكترونية للبلدية أو بموعد محجوز.', '2026-09-03 21:22:47.265689+00'),
	('b28dc41b-b399-4eb0-a874-4490cf936695', 'ar', 'Ansökan görs i ESF-rådets Projektrummet när en utlysning är öppen.', 'يُقدَّم الطلب في Projektrummet التابع لـ ESF-rådet عندما تكون هناك دعوة مفتوحة.', '2026-09-03 21:22:47.265689+00'),
	('48726601-34bb-4d5d-bfc6-a8914652d634', 'ar', 'Ansökan görs i EU:s ansökningssystem (kräver EU Login och OID).', 'يُقدَّم الطلب في نظام التقديم التابع للاتحاد الأوروبي (يتطلب EU Login ورقم OID).', '2026-09-03 21:22:47.265689+00'),
	('c9d0200a-2cb3-40bd-b7e4-d299fa0395bb', 'ar', 'Ansökan görs i EU:s ansökningssystem (kräver EU Login, OID och Quality Label).', 'يُقدَّم الطلب في نظام التقديم التابع للاتحاد الأوروبي (يتطلب EU Login ورقم OID وشهادة Quality Label).', '2026-09-03 21:22:47.265689+00'),
	('8cbd7d3e-c927-478f-ad91-4b60b777b7f3', 'ar', 'Ansökan görs i EU:s Funding & Tenders-portal (kräver EU Login och PIC/OID).', 'يُقدَّم الطلب عبر بوابة Funding & Tenders التابعة للاتحاد الأوروبي (يتطلب EU Login ورقم PIC/OID).', '2026-09-03 21:22:47.265689+00'),
