	('80c78504-91eb-4520-96fd-d9e34e97d709', 'ar', 'Grundskydd för den som haft låg eller ingen arbetsinkomst under livet.', 'حماية أساسية لمن كان دخله من العمل قليلًا أو معدومًا خلال حياته.', '2026-09-03 21:22:47.282373+00');
INSERT INTO public.kb_translations VALUES
