INSERT INTO public.kb_translations VALUES
	('7567942d-be5a-4761-8d86-99e4b0bcf789', 'fa', 'Prövar projektet nya konstnärliga uttryck, metoder eller samarbeten?', 'آیا پروژه بیان‌ها، روش‌ها یا همکاری‌های هنری تازه‌ای می‌آزماید؟', '2026-09-03 21:22:47.340112+00'),
	('db5901f4-3b0a-4ca3-80b9-e4f5a3617258', 'fa', 'Publik verksamhet', 'فعالیت رو به عموم', '2026-09-03 21:22:47.340112+00'),
	('0925b696-f0fb-42a6-bd15-b0cd5efd3d24', 'fa', 'Pågående vård eller insatser', 'مراقبت یا خدمات جاری', '2026-09-03 21:22:47.340112+00'),
	('2dbc6d5c-d2df-471a-ad53-32029b30e33d', 'fa', 'Pågår utbytet 5–21 dagar (exklusive resdagar)?', 'آیا تبادل ۵ تا ۲۱ روز طول می‌کشد (بدون روزهای سفر)؟', '2026-09-03 21:22:47.340112+00'),
	('e1897bc9-14eb-479d-ae11-8b2ea7ee8212', 'fa', 'Regionernas egna projekt- och verksamhetsstöd till kulturlivet, vid sidan av Kulturrådets nationella bidrag.', 'حمایت‌های خود استان‌ها از پروژه‌ها و فعالیت‌های فرهنگی، در کنار کمک‌های ملی Kulturrådet.', '2026-09-03 21:22:47.340112+00'),
	('e0d2beda-0145-4f5a-ad3f-e6219938c285', 'fa', 'Regissör och tidigare verk', 'کارگردان و آثار پیشین', '2026-09-03 21:22:47.340112+00'),
	('893ec756-8081-4056-974c-5582d7976f4f', 'fa', 'Registrerar föreningen närvaro digitalt (t.ex. IdrottOnline)?', 'آیا انجمن حضور را به‌صورت دیجیتال ثبت می‌کند (برای نمونه در IdrottOnline)؟', '2026-09-03 21:22:47.340112+00'),
	('1352914e-cb89-43b2-a5e9-e26df34a5368', 'fa', 'Registreras i EU:s Organisation Registration System — utan OID kan ansökan inte lämnas in.', 'ثبت‌نام در Organisation Registration System اتحادیه اروپا انجام می‌شود — بدون OID درخواست قابل ارسال نیست.', '2026-09-03 21:22:47.340112+00'),
	('552b1143-d4a5-41ed-9c1f-829718c9017f', 'fa', 'Registreras i EU:s Organisation Registration System med EU Login.', 'ثبت‌نام در Organisation Registration System اتحادیه اروپا با EU Login انجام می‌شود.', '2026-09-03 21:22:47.340112+00'),
	('47d7277c-884f-4a7b-a0b7-51a728ff67e9', 'fa', 'Repertoar, produktioner, spelplatser och publik — verksamhetsbidraget bedöms på helheten, inte enskilda projekt.', 'رپرتوار، تولیدات، مکان‌های اجرا و مخاطب — کمک‌هزینه فعالیت بر پایه کل کار سنجیده می‌شود، نه پروژه‌های منفرد.', '2026-09-03 21:22:47.340112+00'),
	('d5f7553a-746d-42ae-9834-b9f64f8d167f', 'fa', 'Resan och utbytet', 'سفر و تبادل', '2026-09-03 21:22:47.340112+00'),
	('59e3c99f-9991-4515-8973-18b81f9d59bf', 'fa', 'Resebudget', 'بودجه سفر', '2026-09-03 21:22:47.340112+00'),
	('0a8d7d70-042f-4476-a268-2c3b4ce76b88', 'fa', 'Resmål (land)', 'مقصد (کشور)', '2026-09-03 21:22:47.340112+00'),
	('d8a7a390-2f8e-4818-bf19-c34a712c624e', 'fa', 'Resperiod', 'دوره سفر', '2026-09-03 21:22:47.340112+00'),
	('23315a11-0c2a-4864-85f9-ba1e9b67cf5f', 'fa', 'Riktar sig projektet till barn eller unga?', 'آیا پروژه کودکان یا جوانان را هدف می‌گیرد؟', '2026-09-03 21:22:47.340112+00'),
	('124cd3ef-c09c-459b-bb10-bb1fe120a757', 'fa', 'Riktar sig projektet till barn, unga, äldre eller personer med funktionsnedsättning?', 'آیا پروژه کودکان، جوانان، سالمندان یا افراد دارای معلولیت را هدف می‌گیرد؟', '2026-09-03 21:22:47.340112+00'),
	('e0ce2b65-d1c7-47c2-965b-8fc6e45fb002', 'fa', 'Riktar sig verksamheten till barn och unga (7–25 år)?', 'آیا فعالیت کودکان و جوانان (۷–۲۵ ساله) را هدف می‌گیرد؟', '2026-09-03 21:22:47.340112+00'),
	('59f22c79-345b-4068-9158-1e7b93fee5d5', 'fa', 'Roller, relevant erfarenhet och hur mycket tid nyckelpersonerna lägger.', 'نقش‌ها، تجربه مرتبط و میزان زمانی که افراد کلیدی صرف می‌کنند.', '2026-09-03 21:22:47.340112+00'),
	('9916a292-6d75-4d98-b0b4-115e4af18882', 'fa', 'Räkna bara kostnader du inte skulle ha utan funktionsnedsättningen — och dra av eventuella bidrag som redan täcker dem.', 'تنها هزینه‌هایی را بشمارید که بدون معلولیت نداشتید — و کمک‌هایی را که هم‌اکنون آن‌ها را پوشش می‌دهند کسر کنید.', '2026-09-03 21:22:47.340112+00'),
	('bfb5e7c0-78bd-4edc-bb06-965119fb7a5a', 'fa', 'Räkna ihop lön, ersättningar och bidrag före skatt. Ungefärligt räcker i förberedelsen — kommunen begär exakta underlag.', 'حقوق، مزایا و کمک‌ها را پیش از کسر مالیات جمع بزنید. در مرحله آماده‌سازی رقم تقریبی کافی است — شهرداری مدارک دقیق را خواهد خواست.', '2026-09-03 21:22:47.340112+00'),
	('c1c9a57c-3eec-4d07-adc5-4f5f43afbe24', 'fa', 'Saknar du sparpengar eller tillgångar som kan täcka utgifterna?', 'آیا پس‌انداز یا دارایی‌ای ندارید که بتواند هزینه‌ها را بپوشاند؟', '2026-09-03 21:22:47.340112+00'),
	('91045203-b51b-42c7-969d-bdcaf4744374', 'fa', 'Samarbetar ni med partner i minst två andra nordiska länder?', 'آیا با شرکایی در دست‌کم دو کشور شمال اروپای دیگر همکاری می‌کنید؟', '2026-09-03 21:22:47.340112+00'),
	('b30332d5-6d3a-4673-a30e-1b0c2035b03a', 'fa', 'Sammanlagt de minimis-stöd senaste tre åren (kr)', 'مجموع کمک de minimis در سه سال گذشته (kr)', '2026-09-03 21:22:47.340112+00'),
	('fb18b8ba-33ff-46fc-a131-0739dcefefd8', 'fa', 'Samtycke krävs när det är möjligt att lämna.', 'در مواردی که امکان دادن رضایت هست، رضایت لازم است.', '2026-09-03 21:22:47.340112+00'),
	('d5803cae-3996-4c0e-b7ce-752ada7db77e', 'fa', 'Senaste verksamhetsberättelse', 'آخرین گزارش سالانه فعالیت‌ها', '2026-09-03 21:22:47.340112+00'),
	('dacdcc3c-edee-4083-b904-90d562184200', 'fa', 'Senaste verksamhetsberättelse och årsredovisning', 'آخرین گزارش سالانه فعالیت‌ها و صورت‌های مالی سالانه', '2026-09-03 21:22:47.340112+00'),
	('918d41c5-956d-4bc9-9413-337f99168f84', 'fa', 'Senaste årsredovisning', 'آخرین صورت‌های مالی سالانه', '2026-09-03 21:22:47.340112+00'),
	('6ac4c3e2-2d80-42a0-b543-88969cc56cb9', 'fa', 'Senaste årsredovisning/verksamhetsberättelse', 'آخرین صورت‌های مالی سالانه یا آخرین گزارش سالانه فعالیت‌ها', '2026-09-03 21:22:47.340112+00'),
	('56a81f43-08c4-4773-b68c-756fb6d75335', 'fa', 'Sjukdomen ska sätta ned din arbetsförmåga med minst en fjärdedel', 'بیماری باید توان کاری شما را دست‌کم یک‌چهارم کاهش دهد', '2026-09-03 21:22:47.340112+00'),
	('dc606471-48d3-4045-aa83-0455957e942c', 'fa', 'Ska ni ta in extern kompetens för en utvecklingsinsats?', 'آیا برای یک اقدام توسعه‌ای تخصص بیرونی به کار می‌گیرید؟', '2026-09-03 21:22:47.340112+00'),
	('7930351e-49ea-4190-accd-3c8242890fb2', 'fa', 'Sker mobiliteten till ett annat europeiskt land?', 'آیا تحرک به کشور اروپایی دیگری است؟', '2026-09-03 21:22:47.340112+00'),
	('9131b059-6ff1-4cba-b251-0324ac60ea40', 'fa', 'Skola och ort', 'مدرسه و محل', '2026-09-03 21:22:47.340112+00'),
	('7d997228-5887-4789-9739-8e4297a3121d', 'fa', 'Skolan och boendet', 'مدرسه و محل اقامت', '2026-09-03 21:22:47.340112+00'),
	('62909060-e934-4125-b2c9-8570fe61a3d9', 'fa', 'Skolans namn', 'نام مدرسه', '2026-09-03 21:22:47.340112+00'),
	('b67fec00-ef09-4c68-9639-337b52d8f359', 'fa', 'Skriv in dig hos Arbetsförmedlingen första arbetslösa dagen; ansök sedan hos din a-kassa (Mina sidor).', 'در نخستین روز بیکاری در Arbetsförmedlingen ثبت‌نام کنید؛ سپس در Mina sidor نزد a-kassa (صندوق بیمه بیکاری) درخواست دهید.', '2026-09-03 21:22:47.340112+00'),
	('b616a106-9f6d-4e05-939c-9e0fd392bfa0', 'fa', 'Skriv in dig hos Arbetsförmedlingen; ersättningen ansöks sedan hos Försäkringskassan.', 'در Arbetsförmedlingen ثبت‌نام کنید؛ سپس کمک‌هزینه نزد Försäkringskassan درخواست می‌شود.', '2026-09-03 21:22:47.340112+00'),
	('daf12cee-b4a1-4355-af82-860ff92c3896', 'fa', 'Skyddet gäller privatpersoner', 'این پوشش شامل اشخاص حقیقی می‌شود', '2026-09-03 21:22:47.340112+00'),
	('2c7082ff-d223-479d-ba2a-67744c406bca', 'fa', 'Småskaliga partnerskap är instegsformatet — enklare aktiviteter, lägre budget, men samma krav på tydligt syfte.', 'شراکت‌های کوچک‌مقیاس، قالب ورودی هستند — فعالیت‌های ساده‌تر، بودجه کمتر، اما همان الزام داشتن هدفی روشن.', '2026-09-03 21:22:47.340112+00'),
	('5cc703ea-1c0b-488f-af74-8e2e0b5c403f', 'fa', 'Specialidrottsförbund', 'فدراسیون ملی ورزشی', '2026-09-03 21:22:47.340112+00'),
	('b3e4d020-95f5-46a8-b5d0-c7025c3e49f5', 'fa', 'Specificera merkostnaderna', 'هزینه‌های اضافی را به تفکیک بنویسید', '2026-09-03 21:22:47.340112+00'),
	('2031bbf0-6aeb-406f-801f-d807e1cfa38a', 'fa', 'Stadgar', 'اساسنامه', '2026-09-03 21:22:47.340112+00'),
	('be9e963c-aa7e-4d92-99da-dcb68c2b3d49', 'fa', 'Startar du eller tar du över företaget för första gången?', 'آیا برای نخستین بار کسب‌وکار را راه می‌اندازید یا تحویل می‌گیرید؟', '2026-09-03 21:22:47.340112+00'),
	('eaa4ea11-067d-4710-baf2-96d45f1d80a1', 'fa', 'Startstöd för den som är 40 år eller yngre och startar eller tar över ett jordbruksföretag.', 'حمایت شروع برای کسی که ۴۰ ساله یا جوان‌تر است و بنگاه کشاورزی راه می‌اندازد یا تحویل می‌گیرد.', '2026-09-03 21:22:47.340112+00'),
	('0a63ceb4-693f-4c4a-ba46-9366f04f75e1', 'fa', 'Stiftelsen stödjer bara projekt i den egna sparbankens verksamhetsområde.', 'این بنیاد تنها از پروژه‌هایی در حوزه فعالیت بانک پس‌انداز خود پشتیبانی می‌کند.', '2026-09-03 21:22:47.340112+00'),
	('130331c8-b998-4e5d-a1b1-0b2e9d6921c8', 'fa', 'Stipendiet bedöms på konstnärlig kvalitet och aktivitet — konkreta verk, uppdrag och planer väger tyngre än ambitioner.', 'این کمک‌هزینه بر پایه کیفیت هنری و فعالیت داوری می‌شود — آثار مشخص، سفارش‌ها و برنامه‌ها وزن بیشتری از آرزوها دارند.', '2026-09-03 21:22:47.340112+00'),
	('87c61e46-7ab8-47a2-8177-a700e888945e', 'fa', 'Stipendiet söks av enskilda konstnärer', 'این کمک‌هزینه را هنرمندان به‌صورت فردی درخواست می‌دهند', '2026-09-03 21:22:47.340112+00'),
	('e83139fa-260a-4c3f-96f8-fc0be805065e', 'fa', 'Stipendium som ger yrkesverksamma konstnärer möjlighet att koncentrera sig på konstnärligt arbete.', 'بورسیه‌ای که به هنرمندان حرفه‌ای امکان می‌دهد بر کار هنری تمرکز کنند.', '2026-09-03 21:22:47.340112+00'),
	('d1290395-a9e4-47f5-bc3a-da70f4848020', 'fa', 'Studerar du, eller planerar du att börja studera?', 'آیا تحصیل می‌کنید یا قصد شروع تحصیل دارید؟', '2026-09-03 21:22:47.340112+00'),
	('3ab4044e-7f1f-417c-be32-daac923b9072', 'fa', 'Studieland', 'کشور محل تحصیل', '2026-09-03 21:22:47.340112+00'),
	('9ebea419-f9e0-4847-afb3-6c7c6d1a49d6', 'fa', 'Studiemedel lämnas längst t.o.m. ca 60 års ålder', 'کمک‌هزینه تحصیلی حداکثر تا حدود 60 سالگی داده می‌شود', '2026-09-03 21:22:47.340112+00');
