	('94b5cca7-e486-4838-a6e1-bdd8f595695c', 'fa', 'Studieperiod du söker för', 'دوره تحصیلی که برای آن درخواست می‌دهید', '2026-09-03 21:22:47.340112+00'),
	('68b148c4-82f9-434f-8c3c-98f286c3540a', 'fa', 'Studierna', 'تحصیل', '2026-09-03 21:22:47.340112+00'),
	('0e07e3d8-7018-401e-92d7-c89bae661ada', 'fa', 'Studierna ska bedrivas utomlands', 'تحصیل باید در خارج از کشور انجام شود', '2026-09-03 21:22:47.340112+00'),
