INSERT INTO public.kb_translations VALUES
	('e84e5449-8e54-4e7c-beac-ed96d0ed5cc6', 'prs', 'Ansökan görs hos din kommun, ofta via e-tjänst eller blankett, med intyg.', 'درخواست به شاروالی محل شما، معمولاً از طریق خدمات الکترونیکی یا فورم، همراه با تصدیق‌های لازم ارائه می‌شود.', '2026-09-03 21:22:47.353801+00'),
	('0e150d8a-00af-496d-bfaf-88a9c3fb0755', 'prs', 'Ansökan görs hos Försäkringskassan; läkarutlåtande krävs.', 'درخواست نزد Försäkringskassan انجام می‌شود؛ راپور داکتر لازم است.', '2026-09-03 21:22:47.353801+00'),
	('521d4143-ade9-4514-a3fe-12646124b908', 'prs', 'Ansökan görs hos Försäkringskassan; läkarutlåtande om funktionsnedsättningen och körkortsuppgifter behövs.', 'درخواست نزد Försäkringskassan انجام می‌شود؛ راپور داکتر در مورد معلولیت و معلومات جواز رانندگی لازم است.', '2026-09-03 21:22:47.353801+00'),
	('8f891812-df9c-497c-96c2-a615b6f57c80', 'prs', 'Ansökan görs hos länsstyrelsen i ditt län, ofta via e-tjänst.', 'درخواست نزد länsstyrelsen (اداره ولایتی) ولایت شما، معمولاً از طریق خدمات الکترونیکی، انجام می‌شود.', '2026-09-03 21:22:47.353801+00'),
	('6a8a9222-38d0-4dda-a483-e79d9da37179', 'prs', 'Ansökan görs hos Migrationsverket före utresan.', 'درخواست پیش از خروج از کشور نزد Migrationsverket انجام می‌شود.', '2026-09-03 21:22:47.353801+00'),
	('ca1d7f5b-d4f0-482c-9f72-6dcf7fa6aecc', 'prs', 'Ansökan görs hos Pensionsmyndigheten (kräver e-legitimation).', 'درخواست نزد Pensionsmyndigheten انجام می‌شود (به e-legitimation، هویت الکترونیکی سویدن، ضرورت دارد).', '2026-09-03 21:22:47.353801+00'),
	('2a2f5787-792f-4e33-bf89-4f931e05eb77', 'prs', 'Ansökan görs hos socialtjänsten i din kommun — ofta via kommunens e-tjänst eller ett bokat besök.', 'درخواست به خدمات اجتماعی شاروالی محل شما ارائه می‌شود — معمولاً از طریق خدمات الکترونیکی شاروالی یا وقت ملاقات قبلی.', '2026-09-03 21:22:47.353801+00'),
