INSERT INTO public.kb_translations VALUES
	('33c49c92-54af-4cf8-a90e-e23b8d8b842c', 'ru', 'Ansökan görs hos CSN med e-legitimation.', 'Заявление подаётся в CSN с помощью e-legitimation (шведский электронный ID).', '2026-09-03 21:22:47.39757+00'),
	('a9506a1e-bc8a-44af-b06a-abb3d4857706', 'ru', 'Ansökan görs hos CSN; omställningsorganisationen kan komplettera med kollektivavtalat stöd.', 'Заявление подаётся в CSN; организация профессионального перехода может дополнить его поддержкой по коллективному договору.', '2026-09-03 21:22:47.39757+00'),
	('f77c57ac-5c9a-4d1e-9359-46097a6e127d', 'ru', 'Ansökan görs hos din kommun, ofta via e-tjänst eller blankett, med intyg.', 'Заявление подаётся в вашу коммуну, часто через электронную услугу или бланк, со справками.', '2026-09-03 21:22:47.39757+00'),
	('9e5b3cd6-9dda-474f-8afb-55a741d52830', 'ru', 'Ansökan görs hos Försäkringskassan; läkarutlåtande krävs.', 'Заявление подаётся в Försäkringskassan; требуется медицинское заключение.', '2026-09-03 21:22:47.39757+00'),
	('2c27fb55-7f01-490a-b087-0628a3bcd2aa', 'ru', 'Ansökan görs hos Försäkringskassan; läkarutlåtande om funktionsnedsättningen och körkortsuppgifter behövs.', 'Заявление подаётся в Försäkringskassan; нужны медицинское заключение об инвалидности и данные водительского удостоверения.', '2026-09-03 21:22:47.39757+00'),
	('c5111cb6-86cd-4443-af67-a4ca137f5c49', 'ru', 'Ansökan görs hos länsstyrelsen i ditt län, ofta via e-tjänst.', 'Заявление подаётся в länsstyrelsen (администрацию лена) вашего лена, часто через электронную услугу.', '2026-09-03 21:22:47.39757+00'),
	('568136e6-c32a-4fcf-8538-d5f2980e4df7', 'ru', 'Ansökan görs hos Migrationsverket före utresan.', 'Заявление подаётся в Migrationsverket до выезда из страны.', '2026-09-03 21:22:47.39757+00'),
	('38ed45ce-0f5e-4143-886e-eb6a03c4278a', 'ru', 'Ansökan görs hos Pensionsmyndigheten (kräver e-legitimation).', 'Заявление подаётся в Pensionsmyndigheten (требуется e-legitimation, шведский электронный ID).', '2026-09-03 21:22:47.39757+00'),
	('fc592321-16a5-4df7-952a-bdd2590d7ca0', 'ru', 'Ansökan görs hos socialtjänsten i din kommun — ofta via kommunens e-tjänst eller ett bokat besök.', 'Заявление подаётся в социальную службу вашей коммуны — часто через электронную услугу коммуны или по записи.', '2026-09-03 21:22:47.39757+00'),
	('554823ca-71ea-4f63-aafa-d51750449c06', 'ru', 'Ansökan görs i ESF-rådets Projektrummet när en utlysning är öppen.', 'Заявка подаётся в Projektrummet у ESF-rådet, когда открыт конкурс.', '2026-09-03 21:22:47.39757+00'),
	('08596c1f-a89b-443b-a1e6-36cdf221651c', 'ru', 'Ansökan görs i EU:s ansökningssystem (kräver EU Login och OID).', 'Заявка подаётся в системе подачи заявок ЕС (нужны EU Login и OID).', '2026-09-03 21:22:47.39757+00'),
	('870286a2-51b1-4d74-abf1-efd4bf7e4537', 'ru', 'Ansökan görs i EU:s ansökningssystem (kräver EU Login, OID och Quality Label).', 'Заявка подаётся в системе подачи заявок ЕС (нужны EU Login, OID и Quality Label).', '2026-09-03 21:22:47.39757+00'),
	('a93b797a-ea1f-490a-ae2c-02d465ec95cc', 'ru', 'Ansökan görs i EU:s Funding & Tenders-portal (kräver EU Login och PIC/OID).', 'Заявка подаётся на портале ЕС Funding & Tenders (нужны EU Login и PIC/OID).', '2026-09-03 21:22:47.39757+00'),
	('2367b9da-f89d-46ce-a4fa-e3bde8c38604', 'ru', 'Ansökan görs i finansiärens officiella ansökningstjänst.', 'Заявка подаётся в официальном сервисе подачи заявок финансирующей организации.', '2026-09-03 21:22:47.39757+00'),
	('f0617a31-9f96-4da1-ab3c-83a620abb3d2', 'ru', 'Ansökan görs i Jordbruksverkets e-tjänst (kräver e-legitimation; fullmakt kan användas).', 'Заявка подаётся в электронной услуге Jordbruksverket (нужна e-legitimation; можно использовать доверенность).', '2026-09-03 21:22:47.39757+00'),
	('8fea78ac-4839-4ae2-b67c-abff10207ffa', 'ru', 'Ansökan görs i Jordbruksverkets e-tjänst (kräver e-legitimation).', 'Заявка подаётся в электронной услуге Jordbruksverket (нужна e-legitimation, шведский электронный ID).', '2026-09-03 21:22:47.39757+00'),
	('3ce2e491-acea-4f39-93f9-86a304cd9a9e', 'ru', 'Ansökan görs i Kulturrådets onlinetjänst när omgången är öppen.', 'Заявка подаётся в онлайн-сервисе Kulturrådet, когда открыт очередной раунд.', '2026-09-03 21:22:47.39757+00'),
	('760681f3-ee37-4fa7-b5cc-a75a9b1f94c1', 'ru', 'Ansökan görs i Kulturrådets onlinetjänst.', 'Заявка подаётся в онлайн-сервисе Kulturrådet.', '2026-09-03 21:22:47.39757+00'),
	('ffe14960-8189-44e6-a3fd-a220920be88b', 'ru', 'Ansökan görs i Mina sidor hos CSN (kräver e-legitimation).', 'Заявление подаётся в Mina sidor на сайте CSN (нужна e-legitimation, шведский электронный ID).', '2026-09-03 21:22:47.39757+00'),
