INSERT INTO public.kb_translations VALUES
	('790efbae-33e2-4787-8c41-0eb62eee9a04', 'ti', 'Beskriv svårigheterna att förflytta dig eller resa kollektivt', 'ኣብ ምንቅስቓስ ወይ ኣብ ምጥቃም ህዝባዊ መጓዓዝያ ዘጋጥሙኻ ጸገማት ግለጽ', '2026-09-03 21:22:47.531655+00'),
	('daeb06f1-dd6b-4701-9487-255e2cbbad50', 'ti', 'Beskriv tillgångarna', 'ነተን ንብረት ግለጽ', '2026-09-03 21:22:47.531655+00'),
